INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (1, 'al-nahw-al-wadih', 'al-nahw-al-wadih-%d8%a7%d9%84%d9%86%d8%ad%d9%88-%d8%a7%d9%84%d9%88%d8%a7%d8%b6%d8%ad', 1262, 'al Nahw al Wadih', 'النحو الواضح', '<p><em>Al-Naḥw al-Wāḍiḥ fī Qawāʿid al-Lughah al-ʿArabiyyah lil-Madāris al-Ibtidāʾiyyah</em> — all three parts compiled into a single hardback volume, presented in a two-colour print edition.</p>', 600, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (2, 'sharh-qatr-al-nada-wa-bal-al-sada-arabic', 'sharh-qatr-al-nada-wa-bal-al-sada-arabic-%d8%b4%d8%b1%d8%ad-%d9%82%d8%b7%d8%b1-%d8%a7%d9%84%d9%86%d8%af%d9%89-%d9%88%d8%a8%d9%84-%d8%a7%d9%84%d8%b5%d8%af%d9%89', 1258, 'Sharh Qatr al Nada wa Bal al Sada Arabic', 'شرح قطر الندى وبل الصدى', '<p>Imām Ibn Hishām’s renowned primer in Naḥw, accompanied by an Arabic commentary, printed in a single hardback volume with a two-colour layout.</p>', 350, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (3, 'hidayah-al-nahw', 'hidayah-al-nahw-%d9%87%d8%af%d8%a7%d9%8a%d8%a9-%d8%a7%d9%84%d9%86%d8%ad%d9%88', 1255, 'Hidayah al Nahw', 'هداية النحو', '<p>A renowned primer in Naḥw, taught in institutes across the world, published in hardback by Maktabah al Bushra, complete with beneficial footnotes</a></p>', 300, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (4, 'usul-al-shashi', 'usul-al-shashi-%d8%a7%d8%b5%d9%88%d9%84-%d8%a7%d9%84%d8%b4%d8%a7%d8%b4%d9%8a', 1251, 'Usul al Shashi', 'اصول الشاشي', '<p>A renowned primer in Ḥanafī Uṣūl al-Fiqh, published by Maktabah al Bushra</a> in hardback, featuring <em>Aḥsan al-Ḥawāshī</em> (2024/2025 edition).</p>', 300, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (5, 'asaan-bayaan-al-quran-with-tafsir-uthmani', 'asaan-bayaan-al-quran-with-tafsir-uthmani-%d8%a2%d8%b3%d8%a7%d9%86-%d8%a8%d9%8a%d8%a7%d9%86-%d8%a7%d9%84%d9%82%d8%b1%d8%a2%d9%86-%d9%85%d8%b9-%d8%aa%d9%81%d8%b3%d9%8a%d8%b1-%d8%b9%d8%ab%d9%85%d8%a7', 1248, 'Asaan Bayaan al Quran With Tafsir Uthmani', 'آسان بيان القرآن مع تفسير عثماني', '<p> Hz Mawlana Ashraf Ali Thanwi ’s masterpiece tafsīr, published in a simplified and accessible format with additional explanatory footnotes in 3 volumes, together with <em>Tafsīr ʿUthmānī</em> by Hz Mawlana Shabbir Ahmad Usmani, one of the most widely studied and relied-upon Urdu tafsīrs of the Qurʾān.</p> <p>Annotations and abridgment done by Mawlana Anwar Badakhshani</p>', 2500, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (6, 'bayan-al-quran', 'bayan-al-quran-%d8%a8%d9%8a%d8%a7%d9%86-%d8%a7%d9%84%d9%82%d8%b1%d8%a2%d9%86', 1244, 'Bayan al Quran', 'بيان القرآن', '<p> Hz Mawlana Ashraf Ali Thanwi ’s masterpiece tafsīr in Urdu, published in 3 volumes in a beautifully typeset computerised edition, featuring a two-colour glossy-paper print in a large-format layout by Maktabah al-Bushrā</a></p>', 2000, 0, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (7, 'qisas-al-quran-2-volumes', 'qisas-al-quran-2-volumes-%d9%82%d8%b5%d8%b5-%d8%a7%d9%84%d9%82%d8%b1%d8%a2%d9%86', 1241, 'Qisas al Quran 2 Volumes', 'قصص القرآن', '<p><em>Qiṣaṣ al-Qurʾān</em>, authored by a distinguished student of Anwar Shah Kashmiri , now published in two substantial volumes filled with valuable scholarly insights (fawāʾid), featuring a high-quality two-colour print by Maktabah al-Bushrā</a></p>', 900, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (8, 'bayadhi-quran-majid', 'bayadhi-quran-majid-%d8%a8%d9%8a%d8%a7%d8%b6%d9%8a-%d9%82%d8%b1%d8%a2%d9%86', 1237, 'Bayadhi Quran Majid', 'بياضي قرآن', '<p>16 Line hardback study Mushaf by Maktabah al Bushra A4</p>', 1300, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (9, 'mukhtasar-al-maaniy', 'mukhtasar-al-maaniy-%d9%85%d8%ae%d8%aa%d8%b5%d8%b1-%d8%a7%d9%84%d9%85%d8%b9%d8%a7%d9%86%d9%8a', 1234, 'Mukhtasar al Maaniy', 'مختصر المعاني', '<p><em>Mukhtaṣar al-Maʿānī</em>, the celebrated masterpiece of Imam Saʿd al-Dīn al-Taftāzānī , now published in a single large A4-sized volume by Maktabah al-Bushrā</a>, featuring multiple ḥawāshī</p>', 750, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (10, 'al-tawdih-wal-talwih', 'al-tawdih-wal-talwih-%d8%a7%d9%84%d8%aa%d9%88%d8%b6%d9%8a%d8%ad-%d9%88%d8%a7%d9%84%d8%aa%d9%84%d9%88%d9%8a%d8%ad', 1229, 'al Tawdih wal Talwih', 'التوضيح والتلويح', '<p><em>Al-Tawḍīḥ</em>, the commentary on <em>al-Tanqīḥ</em> in Uṣūl al-Fiqh, together with <em>al-Talwīḥ</em> and the supplementary commentary <em>al-Tawshīḥ</em>, now published in a single comprehensive volume by Maktabah al-Bushrā</a> (2021 edition).</p>', 800, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (11, 'taysir-mustalah-al-hadith', 'taysir-mustalah-al-hadith', 1206, 'Taysir Mustalah al-Hadith', 'تيسير مصطلح الحديث', '<p>Authored by Dr. Maḥmūd al-Ṭaḥān, this book is designed to facilitate the study of the science of ḥadīth and is widely used in contemporary study circles. Written with the average student in mind, it simplifies complex concepts and presents them in an accessible manner. The author summarizes the various scholarly opinions of the past regarding <em>Muṣṭalaḥ al-Ḥadīth</em>, making it an ideal textbook for beginners. The work also serves as a concise summary of Ḥāfiẓ Ibn Ḥajar al-ʿAsqalānī’s <em>Sharḥ Nukhbah</em>, providing a clear and practical guide for students entering the field.</p>', 300, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (12, 'tashil-al-zaruri-li-masail-al-quduri', 'tashil-al-zaruri-li-masail-al-quduri', 1201, 'Tashil al-Zaruri li Masa’il al-Quduri', 'تسهيل الضروري لمسائل القدوري', '<p>2428 Questions and Answers Covering Nearly 12,500 Legal Rulings from <em>Mukhtaṣar al-Qudūrī</em></p> <p>This work is a clear and accessible commentary on <em>Mukhtaṣar al-Qudūrī</em> by Mufti ʿĀshiq Ilāhī, presented in a concise question-and-answer format. Written in a simple and lucid style, it is designed to make the dense legal discussions of the original text easier to understand, and includes explanatory notes wherever the author deemed clarification necessary.</p> <p><em>Mukhtaṣar al-Qudūrī</em>, authored by Imām ʿAbd al-Ḥusayn Aḥmad ibn Abī Bakr al-Qudūrī, is one of the foundational texts of the Ḥanafī school and is taught in seminaries worldwide. Encompassing nearly 12,500 legal rulings, it covers a comprehensive range of subjects, including acts of worship, financial transactions, personal and family law, and judicial matters.</p> <p>This commentary simplifies the legal rulings found in the original work and reorganizes them for ease of study. The material is presented in a question-and-answer format, with additional headings introduced for clarity, many of which do not appear in the original text. In certain instances, relevant rulings have also been supplemented from other classical Ḥanafī legal manuals where necessary, making this an especially practical and student-friendly resource.</p>', 500, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (13, 'al-ikhtiyar-li-talil-al-mukhtar-2-volumes', 'al-ikhtiyar-li-talil-al-mukhtar-2-volumes', 1199, 'Al Ikhtiyar Li Ta’lil Al Mukhtar (2 Volumes)', 'الاختيار لتعليل المختار', '<p>New edition of al Ikhtiyar by Allama Mawsili, which is a Sharh of al Mukhtar lil Fatwa, in 2 thick volumes by Maktabah al-Bushra with multiple Hawashiy, including the Haashiyah of Mufti Abu Lubabah Shah Mansur.</p>', 1000, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (14, 'usul-al-takhrij-wa-dirasah-al-asanid', 'usul-al-takhrij-wa-dirasah-al-asanid', 1197, 'Usul al-Takhrij Wa Dirasah-al-Asanid', 'اصول التخريخ ودراسة الاسانيد', '<p>Authored by Dr. Maḥmūd al-Ṭaḥḥān (best known for his acclaimed work <em>Taysīr Muṣṭalaḥ al-Ḥadīth) </em>this book serves as a clear and practical guide to locating specific ḥadīths and understanding the various types of ḥadīth collections. It also explains how to assess the strength of a chain of transmission, and how to consult the classical works of <em>ʿIlm al-Rijāl</em> to determine the reliability of individual narrators and, consequently, the authenticity of a given narration. An indispensable resource for students of ḥadīth studies.</p>', 250, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (15, 'isaghuji', 'isaghuji', 1194, 'Isaghuji', 'ايساغوجي', '<p>Isāghūjī – A two-colour, computer-typeset edition of the classic primer on Islamic logic, accompanied by the marginal commentary (<em>ḥāshiyah</em>) <em>Mughnī al-Ṭullāb</em> by Maḥmūd Muḥammad Tawfīq al-Būṭī.</p>', 125, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (16, 'durus-al-balagah-bushra', '1189', 1189, 'Durus al Balagah (Bushra)', 'دروس البلاغة', '<p>Durūs al-Balāghah is presented in high-quality two-colour print. This popular work on balāghah (Arabic rhetoric) is supplemented by the authoritative commentary of ʿAllāmah Muḥammad Faḍl Ḥaqq Rāmpūrī, entitled Shumūs al-Barāʿah.</p>', 200, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (17, 'ilm-al-saygah-arabic', 'ilm-al-saygah-arabic', 1185, 'Ilm al Saygah (Arabic)', 'علم الصيغة', '<p><em>Taʿrīb ʿIlm al-Ṣīghah</em> is presented in high-quality two-colour print. This work is an Arabic translation of the renowned ṣarf (Arabic morphology) textbook <em>ʿIlm al-Ṣīghah</em> by Muftī ʿInāyat Aḥmad al-Kākurwī. The translation was carried out by Ustādh Walī Khān al-Muẓaffar under the supervision of Ustādh al-ʿUlamāʾ Shaykh Sālimullāh Khān. The volume also includes additional questions and exercises to aid students in mastering the subject.</p>', 300, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (18, 'talkhis-al-miftah', 'talkhis-al-miftah', 1181, 'Talkhis al Miftah', 'تلخيص المفتاح', '<p>Talkhis al-Miftah &#8211; 2-colour print.</p> <p>A renowned work by Imām Jalāl al-Dīn al-Qazwīnī on balāghah (Arabic rhetoric), enhanced with clear and explanatory footnotes for ease of study. This is a hardback edition.</p>', 250, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (19, 'al-fawz-al-kabir-fi-usul-al-tafsir', 'al-fawz-al-kabir-fi-usul-al-tafsir', 1177, 'Al-Fawz al-Kabir Fi Usul al-Tafsir', 'الفوز الكبير في اصول التفسير', '<p>This is one of the important works of Shāh Walīullāh, originally written in Persian and later translated into Arabic by Muftī Saʿīd Aḥmad Pālanpūrī رحمه الله.</p> <p>The book aims to dispel misconceptions that may arise in the minds of both non-Muslims and some Muslims during the study of the Qur’an. It lays a foundational framework for proper Qur’anic interpretation and discusses the distinctive features and stylistic characteristics of the Qur’anic discourse.</p> <p>Now Hardback by Maktabatul Bushra</p>', 250, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (20, 'nuzhat-al-nazar-fi-tawdih-nukhbah-al-fikr-bushra', 'nuzhat-al-nazar-fi-tawdih-nukhbah-al-fikr-bushra', 1173, 'Nuzhat al-Nazar Fi Tawdih Nukhbah al-Fikr (Bushra)', 'نزهة النظر في توضيح نخبة الفكر', '<p>This is an abridged work on Muṣṭalaḥ al-Ḥadīth (the sciences of ḥadīth). The original text, titled <em>Nukhbat al-Fikr</em>, was authored by Ḥāfiẓ Ibn Ḥajar, who also provided his own authoritative commentary on this foundational primer.</p>', 250, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (21, 'muntakhab-al-husami', 'muntakhab-al-husami', 1170, 'Muntakhab al-Husami', 'منتخب الحسامي', '<p><em>Muntakhab al-Ḥusāmī</em> (also known as <em>al-Muntakhab fī Uṣūl al-Madhhab</em>) is presented in high-quality two-colour print. This work is a foundational text in Ḥanafī uṣūl al-fiqh authored by Imām Ḥusām al-Dīn al-Akhsīkathī, and it is accompanied by the authoritative commentary of ʿAllāmah ʿAbd al-Ḥaqq al-Ḥaqqānī.</p>', 250, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (22, 'diwan-al-hamasa', 'diwan-al-hamasa', 1167, 'Diwan al-Hamasa', 'ديوان الحماسة', NULL, 300, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (23, 'sharh-al-aqidah-al-tahawiyyah-bushra', 'sharh-al-aqidah-al-tahawiyyah-bushra', 1164, 'Sharh al-Aqidah al-Tahawiyyah (Bushra)', 'شرح عقيدة الطحاوية', '<p><em>Sharḥ al-ʿAqīdah al-Ṭaḥāwiyyah</em> by Shaykh al-Muqriʾ Qari Muḥammad Ṭayyib is presented in high-quality two-colour print. This Arabic commentary elucidates the renowned creed of Imām al-Ṭaḥāwī and was authored by the late Chancellor of Dār al-ʿUlūm Deoband, Qārī Ṭayyib Qāsmī Sahib.</p>', 300, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (24, 'sharh-al-aqaaid-al-nasafiyyah-bushra', 'sharah-aqaaid-al-nasafiyyah-bushra', 1161, 'Sharh al-Aqaaid al-Nasafiyyah (Bushra)', 'شرح عقائد النسفية', '<p>This new edition is presented in high-quality, two-colour, computer-typeset print. The text of <em>al-ʿAqāʾid al-Nasafiyyah</em> appears throughout in red and is also included in full as an appendix at the end of the volume. The edition further features the ḥāshiyah <em>ʿIqd al-Farāʾid ʿalā Sharḥ al-ʿAqāʾid</em> by Shaykh Muḥammad ʿAlī.</p> <p>', 300, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (25, 'tafsir-al-jalalayn-with-commentary-2-volume-bushra', 'tafsir-al-jalalayn-with-commentary-2-volume-bushra', 1153, 'Tafsir al-Jalalayn with Commentary [2 Volume] Bushra', 'تفسير الجلالين', '<p>Among the most widely read and celebrated commentaries of the Qur’an, this tafsīr was initially authored by Imām Jalāl al-Dīn al-Maḥallī and later completed by his student, the eminent scholar ʿAllāmah Jalāl al-Dīn al-Suyūṭī.</p> <p>This new, carefully edited edition is presented in high-quality two-colour print and is ideally suited for students of Qur’anic studies.</p> <p>It features a newly prepared ḥāshiyah that distils key insights from some of the most renowned Qur’anic commentaries, including <em>Rūḥ al-Maʿānī</em>, <em>Tafsīr al-Rāzī</em>, <em>Tafsīr al-Khāzin</em>, <em>al-Khaṭīb</em>, <em>al-Kashshāf</em>, <em>Tafsīr Ibn Kathīr</em>, <em>al-Durr al-Manthūr</em>, <em>Rūḥ al-Bayān</em>, <em>Tafsīr Abī al-Suʿūd</em>, <em>al-Bayḍāwī</em>, <em>Ḥāshiyah al-Ṣāwī</em>, <em>al-Kamālayn</em>, <em>Tafsīr al-Aḥmadī</em>, <em>al-Sirāj al-Munīr</em>, and others.</p> <p>In addition, the edition incorporates tafsīr-related aḥādīth sourced from the <em>Ṣaḥīḥayn</em> of al-Bukhārī and Muslim, as well as the Sunan collections of al-Tirmidhī, Abū Dāwūd, al-Nasāʾī, Ibn Mājah, and others, making it a comprehensive and reliable resource for students and scholars alike.</p> <p>', 1500, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (26, 'mishkat-al-masabih-2-volume-bushra', 'mishkat-al-masabih-2-volume-bushra', 1150, 'Mishkat al-Masabih [2 Volume] Bushra', 'مشكاة المصابيح', '<p><strong>Mishkāt al-Maṣābīḥ – New Darsī Edition</strong></p> <p><strong>Complete Set in Two Volumes</strong></p> <p><em>Mishkāt al-Maṣābīḥ</em>, authored by Imām Walī al-Dīn Abū ʿAbdullāh Maḥmūd al-Tabrīzī, is a comprehensive and widely taught collection of ḥadīth studied by students across the Muslim world. In the Indian Subcontinent in particular, it is traditionally taught prior to the six canonical collections (<em>al-Ṣiḥāḥ al-Sittah</em>) in order to adequately prepare students for their advanced study.</p> <p>The majority of the aḥādīth included in <em>Mishkāt al-Maṣābīḥ</em> are drawn from the <em>Ṣiḥāḥ al-Sittah</em>, making it an invaluable foundational text in the study of ḥadīth.</p> <p>This distinguished edition includes:</p> <ul> <li> <p>The ḥāshiyah of Muḥaddith Aḥmad ʿAlī al-Sahāranpūrī</p> </li> <li> <p><em>Muqaddimah fī Muṣṭalaḥāt ʿIlm al-Ḥadīth</em> by Shaykh ʿAbd al-Ḥaqq al-Dehlawī</p> </li> <li> <p><em>al-Ikmāl fī Asmāʾ al-Rijāl</em> by al-Khaṭīb al-Tabrīzī</p> </li> </ul> <p>The set is computer-typeset and presented in high-quality two-colour printing, ensuring clarity and ease of study.</p>', 1500, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (27, 'al-hidayah-sharh-bidayah-al-mubtadi-full-set-4-volumes-fath-al-qadir', 'al-hidayah-sharh-bidayah-al-mubtadi-full-set-4-volumes-fath-al-qadir', 1146, 'Al-Hidayah Sharh Bidayah Al-Mubtadi: (FULL SET 4 VOLUMES) (FATH AL QADIR)', 'الهداية (مع فتح القدير)', '<h3>FULL SET 4 THICK VOLUMES</h3> <h3><strong>1. Al-Hidāyah (الهداية)</strong></h3> <p><strong>Author:</strong> <em>Al-Hidāyah</em> was authored by Imām al-Marghīnānī, a distinguished Ḥanafī jurist from Central Asia. It is regarded as one of the most authoritative and widely studied works in the Ḥanafī school of Islamic jurisprudence.</p> <p><strong>Content:</strong> The work is a comprehensive legal manual that systematically expounds the principles and rulings of Ḥanafī fiqh. It covers a broad range of legal topics, including acts of worship, transactions, family law, and criminal law, presenting them with scholarly precision and depth.</p> <p><strong>Importance:</strong> <em>Al-Hidāyah</em> is a commentary on <em>Bidāyat al-Mubtadī</em> and serves as an essential guide for students and scholars seeking to understand the intricacies of Ḥanafī legal reasoning and rulings.</p> <h3><strong>2. Bidāyah al-Mubtadī (بداية المبتدي)</strong></h3> <p><strong>Author:</strong> This foundational text was written by Imām al-Qudūrī, one of the most eminent jurists of the Ḥanafī school. It was composed as a concise introduction to Ḥanafī jurisprudence for beginners and students.</p> <p><strong>Content:</strong> <em>Bidāyat al-Mubtadī</em> presents essential legal rulings in a clear and simplified format, focusing on core aspects of fiqh without extensive legal argumentation.</p> <p><strong>Use:</strong> The text is widely taught to beginners in Ḥanafī jurisprudence and serves as a stepping stone to more advanced legal works, including <em>Al-Hidāyah</em>.</p> <h3><strong>3. Fatḥ al-Qadīr (فتح القدير)</strong></h3> <p><strong>Author:</strong> <em>Fatḥ al-Qadīr</em> was authored by Imām Kamāl al-Dīn Ibn al-Humām, a leading Ḥanafī jurist and legal theorist.</p> <p><strong>Content:</strong> This work is an in-depth commentary on <em>Al-Hidāyah</em>, offering detailed analysis, clarification, and evidentiary discussion of its legal rulings. It engages with proofs, comparative opinions, and legal reasoning, making it a vital resource for advanced study.</p> <p><strong>Significance:</strong> When studied alongside <em>Al-Hidāyah</em>, <em>Fatḥ al-Qadīr</em> provides a fuller and more nuanced understanding of the Ḥanafī legal methodology, and is considered an indispensable reference for advanced students and scholars of Islamic law.</p>', 4500, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (28, 'al-hidayah-sharh-bidayah-al-mubtadi-full-set-4-volumes', 'al-hidayah-sharh-bidayah-al-mubtadi-full-set-4-volumes', 1140, 'Al-Hidayah Sharh Bidayah Al-Mubtadi: (FULL SET 4 VOLUMES)', 'الهداية (مع حاشية اللكهنوي)', '<p>All 4 Volumes set at a discounted price!</p> <p>Al-Hidāyah, the celebrated commentary on <em>Bidāyat al-Mubtadī</em>, is presented here in a new edition comprising the final two volumes of Imām al-Marghīnānī’s landmark work in Ḥanafī jurisprudence.</p> <p>This is a newly prepared critical edition, elegantly printed in two colours, with the original text of <em>Bidāyat al-Mubtadī</em> highlighted in red for ease of reference.</p> <p>The edition is further enriched by the inclusion of:</p> <ul> <li>The ḥāshiyah of ʿAllāmah ʿAbd al-Ḥayy al-Lakhnawī</li> <li>Taʿlīqāt by Muftī Abū Lubābah Shāh Manṣūr</li> <li><em>Al-Dirāyah fī Takhrīj Aḥādīth al-Hidāyah</em> by Imām Ibn Ḥajar al-ʿAsqalānī</li> <li>Scholarly taʿlīqāt by Maktabah al-Bushrā, highlighting Ḥanafī responses to critical objections</li> </ul>', 3200, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (29, 'al-hidayah-sharh-bidayah-al-mubtadi-3-4-bushra', 'al-hidayah-sharh-bidayah-al-mubtadi-3-4-bushra', 1135, 'Al-Hidayah Sharh Bidayah Al-Mubtadi: (3 & 4) Bushra', 'الهداية (مع حاشية اللكهنوي)', '<p>Al-Hidāyah, the celebrated commentary on <em>Bidāyat al-Mubtadī</em>, is presented here in a new edition comprising the final two volumes of Imām al-Marghīnānī’s landmark work in Ḥanafī jurisprudence.</p> <p>This is a newly prepared critical edition, elegantly printed in two colours, with the original text of <em>Bidāyat al-Mubtadī</em> highlighted in red for ease of reference.</p> <p>The edition is further enriched by the inclusion of:</p> <ul> <li>The ḥāshiyah of ʿAllāmah ʿAbd al-Ḥayy al-Lakhnawī</li> <li>Taʿlīqāt by Muftī Abū Lubābah Shāh Manṣūr</li> <li><em>Al-Dirāyah fī Takhrīj Aḥādīth al-Hidāyah</em> by Imām Ibn Ḥajar al-ʿAsqalānī</li> <li>Scholarly taʿlīqāt by Maktabah al-Bushrā, highlighting Ḥanafī responses to critical objections</li> </ul>', 1700, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (30, 'al-hidayah-sharh-bidayah-al-mubtadi-1-2-bushra', 'al-hidayah-sharh-bidayah-al-mubtadi-1-2-bushra', 1130, 'Al-Hidayah Sharh Bidayah Al-Mubtadi: (1 & 2) Bushra', 'الهداية (مع حاشية اللكهنوي)', '<p>Al-Hidāyah, the celebrated commentary on <em>Bidāyat al-Mubtadī</em>, is presented here in a new edition comprising the final two volumes of Imām al-Marghīnānī’s landmark work in Ḥanafī jurisprudence.</p> <p>This is a newly prepared critical edition, elegantly printed in two colours, with the original text of <em>Bidāyat al-Mubtadī</em> highlighted in red for ease of reference.</p> <p>The edition is further enriched by the inclusion of:</p> <ul> <li>The ḥāshiyah of ʿAllāmah ʿAbd al-Ḥayy al-Lakhnawī</li> <li>Taʿlīqāt by Muftī Abū Lubābah Shāh Manṣūr</li> <li><em>Al-Dirāyah fī Takhrīj Aḥādīth al-Hidāyah</em> by Imām Ibn Ḥajar al-ʿAsqalānī</li> <li>Scholarly taʿlīqāt by Maktabah al-Bushrā, highlighting Ḥanafī responses to critical objections</li> </ul>', 1700, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (31, 'sharh-maaniy-al-athaar-tahawi', 'sharh-maaniy-al-athaar-tahawi', 1125, 'Sharh Maaniy al Athaar (Tahawi)', 'شرح معاني الآثار (الطحاوي)', '<p>Sharḥ Maʿānī al-Āthār — 2 Volumes in 1 Book<br>Covers:</p> <ul> <li> <p>Hadith 1–2831: Ṭahārah to Ṣalāh</p> </li> <li> <p>Hadith 1732–3046: Ṣalāh to Janāʾiz</p> </li> </ul> <p>By Imām Abū Jaʿfar Aḥmad ibn Muḥammad al-Azdī al-Miṣrī al-Ṭaḥāwī (raḥimahullāh)</p> <p>Includes:</p> <ul> <li> <p><em>Maʿ al-Taʿlīqāt al-Ḥāfilah al-Matīʿah</em></p> </li> <li> <p>The ḥāshiyah of ʿAllāmah al-Muḥaddith Wasī Aḥmad al-Sūrtī (raḥimahullāh)</p> </li> <li> <p>The ḥāshiyah of ʿAllāmah al-Muḥaddith Muḥammad Ayyūb al-Saharanpūrī (raḥimahullāh)</p> </li> <li> <p>al-Wāfī fī Ḥall Naẓar al-Ṭaḥāwī by Shaykh Muʿādh Aḥmad Khān</p> </li> <li> <p>At the beginning of Volume 1: al-Ḥāwī fī Sīrat al-Imām Abī Jaʿfar al-Ṭaḥāwī by Shaykh al-ʿAllāmah Zāhid al-Kawtharī (raḥimahullāh)</p> </li> </ul> <p>Format:</p> <ul> <li> <p>Hardback — 494 Pages</p> </li> <li> <p>2 Volumes combined in 1</p> </li> <li> <p>A3 size</p> </li> </ul>', 1000, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (32, 'sunan-ibn-majah-one-thick-volume', 'sunan-ibn-majah-one-thick-volume', 1119, 'Sunan Ibn Majah (One thick Volume)', 'سنن ابن ماجة', '<p>Now in one thick Volume</p> <p>Includes:</p> <ul> <li> <p>Maʿ al-Taʿlīqāt al-Ḥāfilah al-Matīʿah: the marginal notes (<em>ḥāshiyah</em>) of Muḥaddith Fakhr al-Ḥasan al-Gangohī</p> </li> <li> <p>The <em>ḥāshiyah</em> of Imām Muḥammad ibn ʿAbd al-Hādī al-Sindhī</p> </li> </ul> <p>At the end of the book:</p> <ul> <li> <p>al-Imām Ibn Mājah wa Kitābuhu al-Sunan by the eminent scholar and critic ʿAbd al-Rashīd al-Nuʿmānī</p> </li> </ul> <p>With additional notes by Shaykh ʿAbd al-Fattāḥ Abū Ghuddah.</p> <p>Hardback, 981 pages.</p>', 1500, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (33, 'jami-al-tirmidhi-2-volumes', 'jami-al-tirmidhi-2-volumes', 1115, 'Jami al Tirmidhi (2 Volumes)', 'جامع الترمذي', '<p>The Jāmiʿ of Imām al-Tirmidhī holds the third position among the <em>Sihāḥ Sittah</em>—the six canonical collections of ḥadīth.</p> <p>This distinguished edition includes:</p> <ul> <li> <p>al-ʿIlal al-Ṣaghīr by Imām al-Suyūṭī</p> </li> <li> <p>al-Shamāʾil al-Muḥammadiyyah by Imām al-Tirmidhī</p> </li> </ul> <p>It is further enriched with the following acclaimed commentaries:</p> <ul> <li> <p>The <em>ḥāshiyah</em> of Muḥaddith Aḥmad ʿAlī Sahāranpūrī</p> </li> <li> <p>Qut al-Mughtadhī by Imām Jalāl al-Dīn al-Suyūṭī</p> </li> <li> <p>al-ʿArf al-Shadhī by Imām Anwar Shāh Kashmīrī</p> </li> <li> <p>al-Thawāb al-Ḥalī by Mawlānā Ashraf ʿAlī Thānawī</p> </li> <li> <p>The dictations of Shaykh al-Hind Mawlānā Maḥmūd Ḥasan Deobandī</p> </li> </ul> <p>', 2500, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (34, 'sunan-abi-dawud-2-volumes', 'sunan-abi-dawud-2-volumes', 1111, 'Sunan Abi Dawud (2 Volumes)', 'سنن ابي داود', '<p>Sunan Abi Dawud in 2 thick volumes by Maktabatul Bushra</p>', 2200, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (35, 'muwatta-imam-malik', 'muwatta-imam-malik', 1107, 'Muwatta Imam Malik', 'الموطأ للامام مالك', '<p>Muwatta of Imam Malik, now in one thick Volume</p>', 1200, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (36, 'sahih-muslim-2-volumes', 'sahih-muslim-2-volumes', 1103, 'Sahih Muslim (2 Volumes)', 'صحيح مسلم', '<p>Sahih Muslim by Bushra in 2 thick Volumes (2024/2025)</p>', 2600, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (37, 'sunan-al-nasai-one-thick-volume', 'sunan-al-nasai-one-thick-volume', 1100, 'Sunan al Nasai (One thick Volume)', 'سنن النسائي', '<p>Newer edition of Sunan al Nasai now in one thick Volume rather than 2 thinner volumes</p>', 1500, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (38, 'muwatta-imam-muhammad', 'muwatta-imam-muhammad', 1096, 'Muwatta Imam Muhammad', 'الموطأ للامام محمد', '<p>Al-Muwaṭṭaʾ of Imām Muḥammad – With Commentary</p> <p>This is the complete text of <em>Al-Muwaṭṭaʾ</em> as narrated by Imām Muḥammad, accompanied by the full commentary <em>al-Taʿlīq al-Mumajjād</em> by ʿAllāmah ʿAbd al-Ḥayy al-Lakhnawī. This new edition features a clear, two-colour print for improved readability.</p>', 1150, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (39, 'kanz-al-daqaiq-1-large-volume', 'kanz-al-daqaiq-1-large-volume', 1084, 'Kanz al-Daqa’iq (1 Large Volume)', 'كنز الدقائق', '<p>New Edition of Imam ʿAbd Allāh ibn Aḥmad al-Nasafī’s Renowned Work on Ḥanafī Fiqh</p> <p>This is a new, critical edition presented in two-colour print. It includes the insightful commentaries of Shaykh Muhammad Aḥsan al-Siddīqī al-Nanotwī and Ustadh Ḥabīb al-Raḥmān Deobandī, making it an invaluable resource for students and scholars of Ḥanafī jurisprudence.</p>', 850, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (40, 'sahih-al-bukhari-arabic-complete-set-4-volumes-bushra', 'sahih-al-bukhari-arabic-complete-set-4-volumes-bushra', 1081, 'Sahih al-Bukhari [Arabic] – Complete Set (4 Volumes) (BUSHRA)', 'صحيح البخاري', '<p>Sahih al-Bukhari – Complete 4-Volume Set in Two-Colour Print</p> <p>This set presents the most authentic collection of ḥadīth reports compiled by Imam al-Bukhārī, one of the six canonical collections of ḥadīth (<em>al-Kutub al-Siḥah al-Sittah</em>).</p> <p>The volumes also include valuable marginalia:</p> <ul> <li> <p>Ḥāshiyah by Muḥaddith Aḥmad ʿAlī al-Saharānpurī</p> </li> <li> <p>Ḥāshiyah by Imam Abū al-Ḥasan al-Sindī</p> </li> <li> <p>Excerpts from <em>al-Abwāb wa al-Tarājim</em> by Shaykh al-Ḥadīth Muhammad Zakariyya al-Kandahlawī</p> </li> </ul> <p>Edited by a team of scholars under the supervision of Shaykh Muhammad Anīs Rashīd, this edition offers readers both the classical authenticity and scholarly commentary necessary for in-depth study.</p>', 3800, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (41, 'a-handbook-of-spiritual-medicine-paperback', 'a-handbook-of-spiritual-medicine-paperback', 1077, 'A Handbook of Spiritual Medicine (Paperback)', NULL, '<p>This spiritual guide to the self serves as a handbook of <em>tazkiyah</em>, or self-purification. It not only illuminates the maladies of the human soul but also acknowledges the struggles and insecurities we all face, offering practical remedies. These cures are drawn from Qur’ānic verses and authentic ahādīth, inspiring mindfulness of Allah Taala and His Beloved Prophet (SAW).</p> <p>Rooted in the 11th- and 12th-century teachings of the ‘Proof of Islam’ and sage scholar Imam Abu Hamid Muhammad Al-Ghazali (RA), this guide is designed to be relevant and accessible to modern life. Its timeless wisdom can benefit readers of all ages and backgrounds — believers and non-believers alike.</p> <p>The paperback edition is light, compact, and easily portable, making it a thoughtful gift for yourself or a loved one, with elegant gold-foil embossing on the front and back covers.</p>', 1850, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (42, 'keys-to-the-divine-names', 'keys-to-the-divine-names', 1073, 'Keys to the Divine Names', NULL, '<p>The Qur’an declares: <em>“To Allah belong the Most Beautiful Names; so call upon Him by them”</em> (7:180). Since the revelation of this verse, the Names of Allah have held a central and profound place within the Islamic sciences. Renowned scholars such as Imam al-Ghazālī (505 AH) and Ibn al-Qayyim (751 AH) have examined this subject in depth, drawing upon the Qur’an and Sunnah to uncover the subtle and layered meanings behind each Divine Name.</p> <p>This new deluxe edition of <em>The Divine Names</em> presents each Name alongside a corresponding verse from the Qur’an to affirm its authenticity. It also includes poetic reflections from celebrated Muslim poets, capturing their deep love, reverence, and awe for the Creator. To help readers incorporate these Names into their daily devotion, the book offers heartfelt supplications inspired by each Name, making it easier to engage in meaningful duʿāʾs — just as our Lord, the Ever-Answering, has commanded.</p>', 1850, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (43, 'the-book-of-repentance', 'the-book-of-repentance', 1070, 'The Book of Repentance', NULL, '<p>At a time when society encourages people to flaunt their sins and take ‘pride’ in wrongdoing, it is more important than ever to revive awareness of tawbah — sincere repentance. From Allah’s immense mercy to His servants is that the doors of repentance remain open until one’s final breath. Our Creator, the Most Subtle, knows that human beings will inevitably make mistakes and commit sins.</p> <p>This short book compiles sections of Shaykh Muḥammad Metwally ash-Shaʿrāwī’s lectures that explore the various facets of repentance, helping readers understand its reality and necessity. It also includes discussions centred on Allah’s infinite mercy, so that we never tire from seeking forgiveness. To provide a comprehensive perspective, these sections are accompanied by Ibn ʿAsākir’s <em>Kitāb at-Tawbah</em> and Ibn Rajab’s <em>Asbāb al-Maghfirah</em>. The combination of these works on repentance, Allah’s mercy, and His forgiveness offers an invaluable source of guidance and a means for eternal benefit, bi-idhni ’llāh.</p>', 350, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (44, 'duas-for-end-of-life', 'duas-for-end-of-life', 1066, 'Duas for End of Life', NULL, '<p>Taken from <em>A Tentative Guide to Islamic Invocations</em> by Prince Ghazi bin Muhammad, this concise yet invaluable collection provides the essential supplications to be recited when approaching the threshold of truth and death. Drawn from the vast treasury of Qur’ānic verses and Prophetic invocations, it includes only the most necessary litanies. Readers can be confident that this collection contains all that is needed as a loved one’s passing (or even their own) draws near.</p>', 350, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (45, 'jami-at-tirmidhi-chapters-on-judicial-judgements-explained', 'jami-at-tirmidhi-chapters-on-judicial-judgements-explained', 1063, 'Jami at-Tirmidhi: Chapters on Judicial Judgements Explained', NULL, '<p>The Book on Judicial Judgements, one of the forty-six chapters contained in Imam al-Tirmidhī’s <em>Jāmiʿ</em>, specifically discusses rulings related to judgeship and legal decisions issued in a court setting. Drawing on his twenty years of experience serving as a judge on the Sharīʿat Appellate Bench of the Supreme Court of Pakistan (1982–2002), Imam Muftī Muḥammad Taqī Usmānī’s commentary on this chapter is an invaluable resource for both students and scholars.</p> <p>Originally delivered as a series of lectures at the renowned seminary <em>Jāmiʿah Dār al-ʿUlūm Karachi</em>, this commentary explains in detail how the legal positions of the various schools of law (madhāhib) are derived from, and shaped by, the aḥādīth presented in this chapter.</p>', 600, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (46, 'jami-at-tirmidhi-the-introduction', 'jami-at-tirmidhi-the-introduction', 1060, 'Jami at-Tirmidhi: The Introduction', NULL, '<p>In a concise yet comprehensive and accessible style, Muftī Muḥammad Taqī Usmānī clarifies many essential subjects within the sciences of ḥadīth (ʿulūm al-ḥadīth). Among the topics he addresses are the authority of ḥadīth as a source of legal proof, the historical development of ḥadīth compilation, and the principles by which narrations are authenticated and graded.</p> <p>This valuable introduction also explains the meaning of <em>aṣḥāb ar-raʾy</em> and responds to the objections raised against Imam Abū Ḥanīfah regarding ḥadīth. Furthermore, the author presents a much-needed discussion on the concept of following an imam (<em>taqlīd</em>), followed by a biographical overview of Imam Tirmidhī and the distinguishing features of his <em>Jāmiʿ</em>.</p> <p>This indispensable work is highly recommended for students of ḥadīth and fiqh, as well as anyone studying Imam Abū ʿĪsā al-Tirmidhī’s celebrated masterpiece.</p>', 900, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (47, 'arbauna-hadith-arabic-40-hadiths', 'arbauna-hadith-arabic-40-hadiths', 1056, 'Arbauna Hadith, (Arabic) 40 hadiths', NULL, '<p>This compilation not only introduces readers to forty important hadiths, but also serves as an effective resource for strengthening Arabic grammar (<em>naḥw</em>) and sentence analysis (<em>tarkīb</em>). Through studying these narrations, learners can develop both their linguistic skills and their understanding of the Prophet’s teachings.</p>', 850, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (48, 'qiraah-al-rashidah-3-parts-in-1-vol-arabic-only', 'qiraah-al-rashidah-3-parts-in-1-vol-arabic-only', 1052, 'Qiraah al Rashidah (3 Parts in 1 Vol) (Arabic Only)', NULL, '<p>This series consists of books written in clear, accessible Arabic specifically designed for students learning the language.</p> <p>Shaykh Abul Hasan ‘Ali Nadwi developed this collection because the Arabic textbooks available for teaching advanced learners were largely secular. He felt it was necessary to produce books that would not only build language skills but also convey essential Islamic teachings. These works are now widely used in many Dārul-‘Ulūms in India and Pakistan, as well as in numerous universities across the Arab world.</p> <p><em>Qirāʾat al-Rāshidah</em>, the original Arabic text, addresses a broad range of Islamic themes, including etiquette (ādāb), notable personalities, and other important topics. Those who can read Arabic may benefit further by enlarging the pages and studying the text closely.</p>', 850, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (49, 'sirah-khatam-al-nabiyin-qasas-al-nabiyyin-part-5-arabic', 'sirah-khatam-al-nabiyin-qasas-al-nabiyyin-part-5-arabic', 1048, 'Sirah Khatam al-Nabiyin (Qasas al Nabiyyin Part 5) (Arabic)', NULL, '<p>This is Volume 5—the final volume—of Mawlana Nadwi’s <em>Qasas al-Nabiyyīn</em>, presented in simple Arabic with full vowel markings (tashkīl/i‘rāb).</p> <p>Designed specifically for students of the Arabic language, this series is recognised for its straightforward style and rich content. The combination of clarity and depth makes it an inspiring and beneficial read for young learners. If you are looking for an accessible Arabic book on the life of the Prophet Muhammad (ﷺ), this volume is an excellent choice.</p> <p>What distinguishes this book from many others is its comprehensive coverage of events, modern illustrated maps, well-crafted review questions for each chapter (workbook style), a transliteration table, and a detailed glossary of Arabic terms. These features make it especially suitable for classroom instruction and structured learning.</p>', 800, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (50, 'qasas-al-nabiyeen-parts-1-4-arabic-only-new-edition', 'qasas-al-nabiyeen-parts-1-4-arabic-only-new-edition', 1045, 'Qasas Al-Nabiyeen (Parts 1-4 ) Arabic Only (New Edition)', NULL, '<p>This is the Arabic original of the well-known English translation <em>Stories of the Prophets</em> by Mawlana Abul Hasan Ali Nadwi. This 179-page Hardback was authored by one of the greatest masters of the Arabic language in recent times, Shaykh Abul Hasan Ali Nadwi, and was written specifically for students learning Arabic.</p> <p>The book presents vivid and engaging portrayals of fourteen major Prophets mentioned in the Qur’an, using simple and accessible Arabic that makes it ideal for classroom use. The level of Arabic develops progressively from chapter to chapter, making it a valuable resource for learners seeking to build their language skills while deepening their understanding of prophetic history.</p> <p>Excellent High quality edition for Darse Nizami.</p> <p>', 850, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (51, 'hayatus-sahabah-abridged-english-translation', 'hayatus-sahabah-abridged-english-translation', 1041, 'Hayatus Sahabah Abridged [English Translation]', NULL, '<p><strong>An Abridged Edition of Hayatus Sahabah</strong> – Translated by Mufti Afzal Hoosen Elias</p> <p><em>Hayatus Sahabah</em> is a monumental work, presenting a large collection of events and incidents involving the Prophet ﷺ and his Companions رضی الله عنهم. These accounts are meticulously categorized according to the lessons and morals they convey.</p> <p>The author has compiled a vast array of information to offer a vivid portrayal of the Sahabah’s dedication to the cause of Da‘wah and the guidance and training they received from the Prophet ﷺ. The work leaves a lasting and profound impression on the reader, illustrating both the challenges and triumphs of the early Muslim community.</p> <p>High Quality Cream Paper edition.</p>', 800, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (52, 'ulama-e-deoband', 'ulama-e-deoband', 1038, 'Ulama-e-Deoband', NULL, '<p>This book highlights six eminent scholars of Deoband, written by various authors and compiled and translated into English by Mufti Afzal Hoosen Elias.</p> <p>A special chapter titled <em>“Why Follow the Ulema of Deoband?”</em> has been included at the end, presenting reasons why one can rely on these scholars, particularly those who adhere to Ahlus Sunnat wal Jamaat.</p> <p>The book outlines the significant achievements of these scholars in fields such as the Qur’an, Sunnah, Ahadith, Fiqh, Tasawwuf, Aqeedah, politics, and Da’wah/tabligh.</p> <p>It also highlights their defense of Islam against falsehoods, including challenges from Christians, Hindus, Shias, Qadianism, Maududism, Barelvism, innovations (bida‘), and extremist interpretations such as Salafism.</p> <p>Their role in the freedom of India.</p>', 250, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (53, 'stories-of-the-prophets', 'stories-of-the-prophets-2', 1035, 'Stories of the Prophets', NULL, '<p><em>Stories of the Prophets</em> recounts the lives of Allah’s major Prophets and has long been used as a key educational resource across the Arab and Muslim world.</p> <p>This English translation from the original Arabic brings Sayyed Abul Hassan’s scholarly work within reach of English-speaking Muslims. Written in a lively and engaging style, the stories provide knowledge, guidance, and inspiration suitable for both adults and children.</p> <p>The book is particularly valuable for schools, as the narratives are drawn directly from the Qur’an and enriched with clear explanations, vivid descriptions, and insightful reflections. Understanding the missions of the Prophets is especially important today, as Muslims strive to remain steadfast on the straight path.</p>', 800, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (54, 'in-the-shade-of-the-green-dome', 'in-the-shade-of-the-green-dome', 1030, 'In the Shade of the Green Dome', NULL, '<p>“Hadrat Haji Ahmed Nakhooda (rahimahullah) initially developed his islahi connection under the guidance of the author of <em>Tarjuman al-Sunnat</em>, the eminent hadith scholar, Hadrat Mawlana Badr-i-‘Alam Mirati Madani (rahimahullah). Acting on his advice, he then pledged bay‘at and undertook his spiritual training (suluk) under the guidance of Qutb al-Aqtab, Shaykh al-Hadith Hadrat Mawlana Muhammad Zakariyya Kandhalwi Madani (rahimahullah), who also granted him khilafat and ijazat.” — Hadrat Mawlana Ebrahim Pandor</p> <p>“He was of an exceedingly simple temperament and lived a life of anonymity. He was deeply devoted to Madinah, and he was especially diligent in reciting Durud, the effects of which permeated his entire life.” — Hadrat Mawlana Sayyid Muhammad ‘Aqil (rahimahullah)</p> <p>“This humble servant read these letters carefully, piece by piece. All of them pertain to guidance on suluk and ihsan, the eradication of base spiritual maladies, and subtle insights into spirituality and self-reformation. It is evident that only such esteemed individuals—those who, in their time, were annihilated in Allah (fana fillah) and immersed deeply in the love of the Prophet ﷺ—could compose such elevated and profound letters.” — Hadrat Mawlana Muhammad Shahid Saharanpuri (rahimahullah)</p>', 750, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (55, '100-stories-of-hadhrat-imam-abu-hanifah', '100-stories-of-hadhrat-imam-abu-hanifah', 1027, '100 Stories of Hadhrat Imam Abu Hanifah', NULL, '<p>A compilation of more than 100 stories from the life Imam Abu Hanifah. Full of deep wisdom and moral lessons, these stories will leave readers marveling at his piety, wisdom, wit, intelligence and steadfastness.</p>', 250, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (56, '100-stories-of-hadhrat-umar-bin-abdul-aziz', '100-stories-of-hadhrat-umar-bin-abdul-aziz', 1024, '100 Stories of Hadhrat Umar bin Abdul Aziz', NULL, '<p>Hundred Stories of Hadhrat Umar bin Abdul Azeez This book contains over a Hundred Stories of the fifth rightful Khalifah, &#8216;Umar the Second&#8217;, &#8216;the fair and just&#8217;, Hadhrat Umar bin Abdul Azeez. These stories refresh ones Iman and will serve as inspiration to adopt a new path in life.</p>', 250, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (57, '100-stories-of-hadrat-abdullah-bin-masood', '100-stories-of-hadrat-abdullah-bin-masood', 1021, '100 Stories of Hadrat Abdullah bin Mas’ood', NULL, '<p>A collection of stories regarding Hadrat Abdullah bin Mas&#8217;ood, a prominent companion and a citadel of knowledge, in which his noble character, knowledge and praiseworthy traits are highlighted.</p>', 250, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (58, '100-stories-of-hadhrat-fatimah', '100-stories-of-hadhrat-fatimah', 1018, '100 Stories of Hadhrat Fatimah', NULL, '<p>This book contains a selection of 100 stories from the life of the Queen of Jannah, Hadhrat Fatimah, which paint a picture of respect, sincerity, piety, contentment simplicity, generosity, compassion, obedience to the Messenger of Allah , and an ardent desire to please Allah, Most High.</p>', 250, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (59, '100-stories-about-hadrat-hasan-and-husayn', '100-stories-about-hadrat-hasan-and-husayn', 1015, '100 Stories About Hadrat Hasan and Husayn', NULL, '<p>very little reliable and authentic literature is available concerning the grandsons of the Messenger of Allah . This book contains 100 authentic and referenced stories from their lives. Their piety, knowledge, good character and love for the Companions is highlighted.</p>', 250, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (60, '100-narratives-of-hadhrat-ali-murtaza', '100-narratives-of-hadhrat-ali-murtaza', 1012, '100 Narratives of Hadhrat Ali Murtaza', NULL, '<p>This book contains 100 interesting narratives of Hadhrat Ali.</p>', 250, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (61, '100-stories-about-hadhrat-umar', '100-stories-about-hadhrat-umar', 1009, '100 Stories About Hadhrat Umar', NULL, '<p>100 stories from the life Hadhrat Umar, originally compiled in Arabic by Sheikh Muhammad Siddique Manshawi.</p>', 250, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (62, '100-stories-about-hadhrat-abu-bakr', '100-stories-about-hadhrat-abu-bakr', 1006, '100 Stories About Hadhrat Abu Bakr', NULL, '<p>100 stories from the life Hadhrat Abu Bakr , originally compiled in Arabic by Sheikh Muhammad Siddique Manshawi.</p>', 250, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (63, 'the-four-imams', 'the-four-imams', 1003, 'The Four Imams', NULL, '<p>This book is a compilation of four works that explore the lives and contributions of the four Imams who founded the great canonical schools of Islamic fiqh: Imam Abu Hanifah, Imam al-Shafi‘i, Imam Malik ibn Anas, and Imam Ahmad ibn Hanbal. Originally written in Arabic by the esteemed Egyptian scholar and theologian Muhammad Abu Zahra, it is now presented in English for the first time.</p> <p>The book provides a comprehensive and in-depth analysis of the four Sunni madhhabs and their founders, detailing their biographies and the methodologies they employed to reach their legal conclusions. This is particularly significant in today’s world, where many Muslims lack sufficient knowledge and, consequently, do not maintain traditional allegiance to a specific madhhab. Such gaps in understanding often lead to unnecessary disagreements within the Muslim community.</p> <p>By making this scholarship accessible in English, the work serves as an important resource for bridging gaps of knowledge, fostering unity among Muslims, and providing a rich and stimulating reading experience for anyone seeking to deepen their understanding of Islam.</p>', 2500, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (64, 'hayatus-sahabah-3-volumes-improved-translation', 'hayatus-sahabah-3-volumes-improved-translation', 997, 'Hayatus Sahabah – 3 Volumes (Improved Translation)', NULL, '<p>This book presents incidents from the life of the Prophet ﷺ and Sahabah, carefully arranged according to the lessons and moral insights they convey.</p> <p>The author has skillfully gathered a vast amount of historical and narrational material to depict the Sahābah’s devotion to da‘wah and their rigorous training under the Prophet ﷺ. The result is a vivid and deeply moving portrayal, one intended to leave a lasting, unforgettable impression on the reader.</p> <p>The work is based primarily on authentic hadith and the writings of reputable classical scholars.</p> <p>This new edition, published by Zam Zam Publishers, features a revised translation and has been edited by Mufti Afzal Hoosen Elias of South Africa.</p>', 2000, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (65, 'shamaail-tirmidhi-with-khasaail-english', 'shamaail-tirmidhi-with-khasaail-english', 994, 'Shamaail Tirmidhi with Khasaail (ENGLISH)', NULL, '<p>This book is a comprehensive compilation of hadith, organised into detailed chapters that beautifully describe the personal character, physical features, habits, and noble etiquette of the Prophet ﷺ. Imām al-Tirmidhī selected precise subject headings and gathered the relevant narrations under each one with great care.</p> <p>The work focuses specifically on the Prophet’s physical qualities and outward character. It begins with the chapter on his blessed features, then continues with chapters on his hair, grooming practices, white hairs, use of kuhl, clothing, ring, sword, armour, turban, manner of sitting, pillow, drinking vessel, fruits, laughter, joking, weeping, and many other aspects of his daily life.</p> <p>This edition is enriched with the acclaimed commentary of Shaykh Muhammad Zakariyya Kandhelwi, offering valuable insights into each narration. It includes the Arabic text, an English translation, and the Shaykh’s detailed explanations.</p> <p><em>Shamā’il al-Tirmidhī with Commentary: Khasā’il-e-Nabawi ﷺ</em><br>by Shaykh al-Hadith Maulana Muhammad Zakariyya Kandhelwi</p>', 800, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (66, 'first-steps-to-understanding-arabic-full-version', 'first-steps-to-understanding-arabic-full-version', 989, 'First Steps to Understanding Arabic (FULL VERSION)', NULL, '<p>A comprehensive introduction to Arabic, in English. Presented in an easy to understand and concise format to make acquiring of Arabic straightforward.</p> <p>Rules are simplified and explained clearly with illustrated examples and ample exercises to consolidate understanding.</p>', 1400, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (67, 'al-sughra-wal-wusta-fi-al-nahw', 'al-sughra-wal-wusta-fi-al-nahw', 960, 'Al Sughra Wal Wusta Fi al-Nahw', NULL, '<p>An advanced continuation of Nahw Al-Wusta and Al-Sughra, this text provides deeper insights into Arabic grammar (Nahw), making it ideal for intermediate learners. It serves as a synthesis of classical Nahw works by esteemed scholars.</p> <p>The book includes a concise Arabic primer on essential Nahw principles, drawing from the <em>Awamil</em> of al-Jurjani, al-Birkwi, and other renowned authorities.</p> <p>Presented in a user-friendly format similar to <em>Al-Sughra</em>, it features additional footnotes that clarify the <em>i‘rab</em> of all examples. Clear headings and color-coded sections make navigation seamless.</p> <p>To further aid comprehension, the book concludes with self-explanatory tables summarising key concepts, allowing learners to quickly grasp and review fundamental ideas.</p>', 400, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (68, 'durus-al-balagah', 'durus-al-balagah', 958, 'Durus Al Balagah', NULL, NULL, 450, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (69, 'first-steps-to-understanding-logic', 'first-steps-to-understanding-logic', 956, 'First Steps to Understanding Logic', NULL, '<p>This is a brief primer in the science of logic, mantiq which is intended to serve as an introduction to the basic terms and concepts of this science which are often mentioned in the text of earlier scholars.</p> <p>It has been written as a hybrid between the Mantiq primers studied in Madaris and formal logics studied outside of Madaris.</p> <p>To keep this book as brief as possible, we have sufficed on a single example for each concept and not included exercise.</p> <p>We have used the English terms in the main text and placed the corresponding Arabic terms in the footnotes.</p>', 300, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (70, 'al-muntakhabat', 'al-muntakhab', 954, 'Al Muntakhabat', NULL, '<p>A rich collection of Arab proverbs, stories, and sayings of the Salaf, alongside accounts of their lives.</p> <p>This work integrates the study of Nahw and Sarf into the translation and analysis, allowing readers to develop both linguistic and contextual understanding. The text is carefully structured, with progressively increasing levels of difficulty and length, enabling learners to advance as their proficiency grows.</p> <p>Sample pages from varying levels are available for preview.</p>', 450, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (71, 'first-steps-to-understanding-urdu', 'first-steps-to-understanding-urdu', 950, 'First Steps to Understanding Urdu', NULL, '<p>First Steps to Understanding Urdu. The author explains, in lucid language, the core concepts of Urdu. Examples are used throughout for ease of understanding. Exercises are also included to aid practical learning.</p>', 950, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (72, 'first-steps-to-understanding-sarf', 'first-steps-to-understanding-sarf', 948, 'First Steps to Understanding Sarf', NULL, '<p>Conjugation of each type of verb with diacritics.</p> <p>Colour coded conjugation tables to help identify patterns and irregularities.</p> <p>Quranic verbs for additional practice.</p> <p>Simpls and concise explanations on constructing irregular verbs.</p> <p>Twelve detailed units comprising of most verb forms.</p>', 950, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (73, 'first-steps-to-understanding-arabic-abridged', 'first-steps-to-understanding-arabic-abridged', 946, 'First Steps to Understanding Arabic Abridged', NULL, '<p>An abridged version of First Steps to Understanding Arabic consisting of core concepts.</p> <p>Self-explanatory charts and tables to summarise key concepts.</p> <p>Six units for beginners to progress to an intermediate level</p>', 450, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (74, 'first-steps-to-reading-urdu', 'first-steps-to-reading-urdu', 943, 'First Steps to Reading Urdu', NULL, '<p>The objective of this book is to help beginners understand how to read Urdu.</p>', 100, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (75, 'first-steps-to-understanding-balagah', 'first-steps-to-understanding-balagah', 940, 'First Steps to Understanding Balagah', NULL, '<p>Balagah is one of the important subjects needed to fully appreciate the Quran.This is why it is taught in most of the madaris.<br> This booklet is a a very basic introduction to the subject.</p>', 280, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (76, 'first-steps-to-understanding-nahw', 'first-steps-to-understanding-nahw', 937, 'First Steps to Understanding Nahw', NULL, '<p>Many books on the subject of Nahw have been written in English. However, most of them are based on classical Arabic texts on Nahw or translations of these texts.<br> This book has been written specifically for English speakers.</p>', 100, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (77, 'sirah-in-30-days', 'sirah-in-30-days', 933, 'Sirah In 30 Days', NULL, '<p>A vibrant and accessible guide to the life of Prophet Muhammad (S), thoughtfully structured into 30 short and memorable lessons for daily learning. Beautifully supported with illustrations, diagrams, and tables, this book makes the Sirah clear and engaging for readers of all ages. It is ideal for children, parents, and anyone seeking an easy yet meaningful introduction to the life of the Beloved Prophet (S).</p> <p>Designed to nurture love, understanding, and reflection, each lesson brings the reader closer to the noble character and timeless example of the Messenger of Allah (S).</p> <p>Learn, love, and live the Sirah!</p> <p>Key Features:</p> <ul> <li> <p>30 concise, memorable lessons covering the blessed life of the Prophet (S).</p> </li> <li> <p>Perfect for daily memorisation, home study circles, and classroom use.</p> </li> <li> <p>Simplifies detailed aspects of the Sirah into clear and engaging summaries.</p> </li> <li> <p>Written in child-friendly language, making it suitable for both young learners and adults.</p> </li> <li> <p>Enhanced with visuals, diagrams, and tables to aid comprehension.</p> </li> <li> <p>Aims to build a deep love, respect, and connection with the Prophet (S).</p> </li> <li> <p>Serves as a solid foundation for further, advanced Sirah study.</p> </li> </ul>', 220, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (78, 'prophet-muhammad-the-perfect-teacher', 'prophet-muhammad-the-perfect-teacher', 930, '[Prophet] Muhammad – The Perfect Teacher', NULL, '<p><strong>Muhammad (may Allah bless him and grant him peace), The Perfect Teacher — An Insight Into His Teaching Methods</strong></p> <p>This remarkable work explores the teaching methods of the Messenger of Allah (may Allah bless him and grant him peace), whose profound influence on his Companions stands as a testament to the unparalleled effectiveness of his instruction.</p> <p>The Prophet’s teaching style was dynamic, varied, and deeply engaging. He employed analogies and similes, shared anecdotes, used diagrams, encouraged interactive dialogue, incorporated gentle humour, repeated key lessons, evaluated his Companions continuously, and made use of appropriate physical contact, gestures, and personalised guidance. Despite being unlettered, he exemplified the qualities of the perfect teacher — a reality that makes this study both fascinating and inspiring.</p> <p>This revised translation of <em>Al-Rasūl al-Mu‘allim</em> presents an exceptional work by the esteemed jurist and ḥadīth scholar Shaykh ‘Abd al-Fattāḥ Abū Ghuddah. It reflects his meticulous research, mastery of the sources, and superior scholarship, offering readers a rich understanding of the Prophet’s noble methods of teaching.</p>', 600, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (79, 'seeratul-mustafa-abridged-edition', 'seeratul-mustafa-abridged-edition', 924, 'Seeratul Mustafa [Abridged Edition]', NULL, '<p>This thick volume is an abridged edition of <em>Seeratul Mustafa</em>. The original work extends across three substantial volumes, and it has been concisely adapted into a single book by the Jamiatul Ulama (KZN) Ta‘limi Board to make it more accessible for students and the general reader. The abridgement focuses primarily on the blessed life of the Messenger of Allah ﷺ, omitting lengthy academic discussions while preserving the essence, beauty, and authenticity of the original work.</p> <p><em>Seeratul Mustafa</em> is regarded by many as the finest of Mawlānā Idrīs Kāndeẖlawī’s literary contributions. It stands out as a radiant masterpiece and enjoys remarkable acceptance within the scholarly community. No Urdu work on the noble Sīrah surpasses it in its depth of research, reliance on primary sources, and clarity of presentation. Mawlānā Kāndeẖlawī masterfully conveys the sentiments, reverence, and aspirations that should reside in the heart of every believer toward the Messenger of Allah ﷺ.</p> <p>This comprehensive biography is rooted in authentic narrations and remains unperturbed by the criticisms of orientalist scholars. The English translation has been produced with care by Mufti Muḥammed Kadwa and Mawlānā Mahomed Mahomedy.</p> <p>Mawlānā Idrīs Kāndeẖlawī completed his studies at Mazāhir al-ʿUlūm (Saharanpur) and Dār al-ʿUlūm Deoband. Among his esteemed teachers were giants such as Mawlānā Khalīl Aḥmad Sahāranpūrī, ʿAllāmah Shabbīr Aḥmad ʿUthmānī, and ʿAllāmah Anwar Shāh Kashmīrī. Distinguished as a scholar of ḥadīth and tafsīr, a poet, and an ascetic, he dedicated his life to the pursuit and teaching of the sacred sciences. He authored numerous important works in tafsīr, ḥadīth, and Islamic theology.</p>', 1050, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (80, 'siratul-mustafa-english-translation-3-volumes', 'siratul-mustafa-english-translation-3-volumes', 915, 'Siratul Mustafa (English Translation) – 3 Volumes', NULL, '<p>A comprehensive biography of the Messenger of Allah ﷺ in the English language. (BOX INCLUDED)</p> <p><em>Seeratul Mustafa</em> — presented here in its complete three-volume English translation — is widely regarded as the crown jewel of Mawlānā Idrīs Kāndeẖlawī’s literary legacy. Among his many works, this masterpiece shines brightest, enjoying unparalleled acceptance and admiration within the scholarly world.</p> <p>No Urdu work on the blessed Sīrah surpasses <em>Seeratul Mustafa</em> in the depth of its research or its reliance on the earliest and most authoritative sources. Mawlānā Kāndeẖlawī not only documents the life of the Messenger of Allah ﷺ with precision and authenticity, but also conveys the reverence, love, and aspirations that every believer should nurture for the Chosen Prophet ﷺ.</p> <p>This monumental work is based primarily on rigorously authenticated narrations and remains untouched by the conjectures and objections of orientalist critics.</p> <p>The English translation has been rendered with great care by Mufti Muḥammad Kadwa and Mawlānā Mahomed Mahomedy.</p> <p>Mawlānā Idrīs Kāndeẖlawī completed his Islamic studies at Mazāhir al-ʿUlūm (Saharanpur) and Dār al-ʿUlūm Deoband. His esteemed teachers included luminaries such as Mawlānā Khalīl Aḥmad Sahāranpūrī, ʿAllāmah Shabbīr Aḥmad ʿUthmānī, and ʿAllāmah Anwar Shāh Kashmīrī. Distinguished as a scholar of ḥadīth and tafsīr, a poet, and an ascetic, he spent his life immersed in the sacred sciences and produced numerous valuable works in the fields of tafsīr, ḥadīth, and Islamic theology.</p>', 2500, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (81, 'the-sublime-conduct-of-rasulullah', 'the-sublime-conduct-of-rasulullah', 911, 'The Sublime Conduct of Rasulullah', NULL, '<p>This compilation brings together an authoritative collection of the noble manners, exalted traits, and exemplary conduct of our beloved Prophet ﷺ, drawn meticulously from numerous reliable works of ḥadīth and sīrah.</p> <p>It is a priceless treasure for every seeker of the Sunnah and for all who are deeply devoted to the perfect way of life embodied by the Messenger of Allah ﷺ.</p> <p>The original work, <em>al-Shamā’il al-Kubrā</em>, was authored in Urdu by Mufti Muḥammad Irshād Qāsmī. This English translation has been prepared by ʿAbd al-Raḥmān ibn Ḥāfiẓ Ḥusayn Kolia, a student of Mawlānā Faḍl al-Raḥmān Aʿẓamī (Former Shaykh al-Ḥadīth of Dār al-ʿUlūm Azaadville).</p>', 900, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (82, 'muhammad-the-last-prophet-a-model-for-all-time', 'muhammad-the-last-prophet-a-model-for-all-time', 908, 'Muhammad The Last Prophet – A Model for all time', NULL, '<p><em>Muḥammad, the Last Prophet</em> presents a comprehensive and engaging account of the blessed life of the final Messenger, Muḥammad ﷺ. This accessible translation enables young English-speaking Muslims to benefit from the distinguished scholarship of Sayyid Abul Ḥasan ʿAlī Nadwī. The work outlines the historical backdrop to the advent of Islam and provides an authentic portrayal of the challenges faced by the Messenger of Allah ﷺ as he guided his misguided society back to the Divine Path.</p> <p>This book offers valuable guidance and inspiration to young Muslims seeking clarity amid the moral confusion of the modern world. By drawing upon the Qur’an and reliable contemporary sources, the author demonstrates how, 1,400 years ago, divine revelation restored order, justice, and harmony to a world engulfed in chaos.</p>', 800, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (83, 'the-beauty-of-prophet-muhammad-saw-vol-1-2-combined', 'the-beauty-of-prophet-muhammad-saw-vol-1-2-combined', 903, 'The Beauty of Prophet Muhammad SAW Vol 1 & 2 Combined', NULL, '<p>Presented here in a newly combined single-volume edition (Volumes 1 &amp; 2), this English work conveys—with clarity and eloquence—the accounts, narratives, and pivotal moments from the life of the Noble Prophet ﷺ, his honoured Companions (raḍiy Allāhu ʿanhum), and the righteous servants of Allah, as found in the Glorious Qur’an, the Hadith, and authoritative historical sources.</p> <p>The Shaykh’s lectures, captured within these pages, provide valuable guidance and profound inspiration for readers of all ages. The path to spiritual refinement—encompassing moral excellence, purity, forgiveness, patience, sacrifice, and selflessness—is outlined with remarkable simplicity and depth. Core concepts of īmān and ʿaqīdah are also explored in a unique and accessible manner.</p> <p>This collection is an essential read for every Muslim, regardless of background, offering timeless lessons and transformative insights.</p>', 550, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (84, 'the-chosen-ones', 'the-chosen-ones', 900, 'The Chosen Ones', NULL, '<p>This book presents discussions on Allah, the story of Ḥaḍrat Mūsā (ʿalayhi as-salām), the life of Khidr (ʿalayhi as-salām), Ḥaḍrat ʿĪsā (ʿalayhi as-salām), and the Sīrah of Rasūlullāh ﷺ—written by various scholars and translated into English by Mufti Afzal Hoosen Elias.</p>', 250, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (85, 'mercy-to-the-world-rahmat-e-aalam-hardback', 'mercy-to-the-world-rahmat-e-aalam-hardback', 897, 'Mercy to the World (Rahmat-e-Aalam) (Hardback)', NULL, '<p><em>Mercy to the World</em> is a remarkable masterpiece by ʿAllāmah Sayyid Sulaymān Nadwī. Drawing upon his vast and profound knowledge of the blessed life of Rasūlullāh ﷺ, he compiled this comprehensive work specifically for school and college students.</p> <p>Written with clarity, beauty, and deep reverence, this book serves as an inspiring introduction to the life and character of the Prophet ﷺ—one that aims not only to inform, but to touch hearts and bring about meaningful change.</p>', 350, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (86, 'muhammad-pbuh-the-beloved-prophet-a-great-story-simply-told', 'muhammad-pbuh-the-beloved-prophet-a-great-story-simply-told', 892, 'Muhammad (PBUH) The Beloved Prophet – A Great Story Simply Told', NULL, '<p>This book is written in a simple, engaging style to help young children enjoy and understand the essence of the blessed life of the Beloved Prophet ﷺ. Presented in 28 short chapters, it portrays the life of Prophet Muḥammad ﷺ as a dynamic and exemplary leader who, through every trial and tribulation, remained steadfast in serving the One and Only God.</p> <p>Comprehensive yet gentle in its approach, the book includes many enriching features designed to capture a child’s imagination—such as summaries of key events, selected Qur’ānic verses, beautiful calligraphy, and appealing illustrations. Each chapter concludes with a set of questions to stimulate reflection and reinforce learning.</p> <p>Ideal for classroom use or as a bedtime read, this book offers young readers an accessible and inspiring introduction to the life of the Prophet ﷺ.</p>', 600, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (87, 'pearls-from-the-path-all-four-parts', 'pearls-from-the-path-all-four-parts', 888, 'Pearls from the Path (ALL FOUR PARTS)', NULL, '<p><em>Pearls from the Path</em> is a captivating collection of meaningful and thought-provoking incidents drawn from the treasured works of Islamic history. Rich in inspiring narratives and timeless lessons, this book rekindles one’s appreciation for the remarkable legacy that Muslims have contributed to humanity.</p> <p>Discover extraordinary accounts of courage and sacrifice, witness the dedication of classical scholars in their pursuit of knowledge, reflect on the challenges endured by the righteous, and learn from the errors and experiences of people throughout the ages. Adults will find guidance relevant to the complexities of modern life, while young readers will realise that history plays a vital role in shaping both the present and the future.</p> <p>Whether you seek to deepen your understanding of Islamic history or wish to introduce your family to the beauty of their heritage, this compilation of short stories serves as an invaluable resource. For those exploring Islam or wishing to learn more about it as a complete way of life, <em>Pearls from the Path</em> provides an accessible and enlightening bridge to greater understanding.</p> <p>Produced to a high standard with a glossy cover and two-colour print, and featuring forewords by distinguished South African scholars, it also makes an ideal gift.</p> <p>ALL FOUR PARTS AS A SET</p>', 2500, 0, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (88, 'islamic-stories-for-muslim-girls-part-2', 'islamic-stories-for-muslim-girls-part-2', 885, 'Islamic stories for Muslim Girls Part 2', NULL, '<p>This series has been compiled to inspire the younger generation of Muslim girls and help them shape their lives according to the teachings of our beautiful religion. Sadly, the widespread availability of un-Islamic material—both in print and online—has led to the corruption of young minds with harmful ideas and misleading values. Today, the worldview of many young females is being shaped by Hollywood and Bollywood, romance novels and blogs, soap operas, glossy magazines, and similar influences.</p> <p>This trend must be reversed, and this series aims to contribute to that positive change. Every story in this book has been taken from authentic Islamic sources. They have been rewritten and thoughtfully presented to appeal to the hearts and minds of young girls, offering them wholesome inspiration and meaningful role models.</p>', 200, 0, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (89, 'islamic-stories-for-muslim-girls-part-1', 'islamic-stories-for-muslim-girls-part-1', 883, 'Islamic stories for Muslim Girls Part 1', NULL, '<p>This series has been compiled to inspire the younger generation of Muslim girls and help them shape their lives according to the teachings of our beautiful religion. Sadly, the widespread availability of un-Islamic material—both in print and online—has led to the corruption of young minds with harmful ideas and misleading values. Today, the worldview of many young females is being shaped by Hollywood and Bollywood, romance novels and blogs, soap operas, glossy magazines, and similar influences.</p> <p>This trend must be reversed, and this series aims to contribute to that positive change. Every story in this book has been taken from authentic Islamic sources. They have been rewritten and thoughtfully presented to appeal to the hearts and minds of young girls, offering them wholesome inspiration and meaningful role models.</p>', 200, 0, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (90, 'islamic-stories-for-muslim-boys-part-2', 'islamic-stories-for-muslim-boys-part-2', 881, 'Islamic stories for Muslim Boys Part 2', NULL, '<p>Do you know who the Ṣaḥābah were? How much do you know about their remarkable lives? The Ṣaḥābah were the blessed companions who lived during the time of <strong>Nabī ﷺ</strong>, and their lives are filled with inspiring stories, noble qualities, and invaluable lessons.</p> <p>Read the stories in this book and try to practise the lessons they teach. Doing so will help you become a better Muslim. The example of the Ṣaḥābah is the finest example to follow. If you make these blessed individuals your role models, you will never lose your way.</p> <p>And don’t forget to share these wonderful stories with your friends—they will love you for teaching them such beautiful and uplifting lessons.</p>', 200, 0, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (91, 'islamic-stories-for-muslim-boys-part-1', 'islamic-stories-for-muslim-boys-part-1', 879, 'Islamic stories for Muslim Boys Part 1', NULL, '<p>Do you know who the Ṣaḥābah were? How much do you know about their remarkable lives? The Ṣaḥābah were the blessed companions who lived during the time of <strong>Nabī ﷺ</strong>, and their lives are filled with inspiring stories, noble qualities, and invaluable lessons.</p> <p>Read the stories in this book and try to practise the lessons they teach. Doing so will help you become a better Muslim. The example of the Ṣaḥābah is the finest example to follow. If you make these blessed individuals your role models, you will never lose your way.</p> <p>And don’t forget to share these wonderful stories with your friends—they will love you for teaching them such beautiful and uplifting lessons.</p>', 200, 0, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (92, 'golden-pages-from-madinah-munawwarah', 'golden-pages-from-madinah-munawwarah', 876, 'Golden Pages from Madinah Munawwarah', NULL, '<p>Madinah Munawwarah holds a unique and sacred place in the heart of every Muslim, for its blessed soil preserves the traces of Prophetic splendour. This radiant city fills the heart with joy and emotion, and standing at its threshold deepens a believer’s spiritual connection to the Prophet ﷺ. Visiting the Rawḍah—the resting place of the Prophet ﷺ—is among the greatest blessings a Muslim can receive. Muslims across the world yearn for this honour, and whoever is granted it should make the most of it by preparing spiritually beforehand. This book offers valuable information about the city of Madinah Munawwarah. Alongside captivating historical accounts spanning centuries of Islamic history, it outlines the virtues of the city, the etiquette to be observed when visiting, and background information on frequently visited sites. It also relates how the pious predecessors expressed profound humility, reverence, and love in the presence of the Prophet ﷺ. By reading this work, visitors to Madinah Munawwarah will—<em>in shāʾ Allāh</em>—find inspiration to spiritually ready themselves for the blessed journey to the city of our beloved Prophet ﷺ.</p>', 350, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (93, 'humorous-anecdotes-from-the-lighter-side-of-islamic-history-volume-2', 'humorous-anecdotes-from-the-lighter-side-of-islamic-history-volume-2', 872, 'Humorous Anecdotes From the lighter side of Islamic History Volume 2', NULL, '<p><strong>It is established through authentic ḥadīths that the Messenger of Allah ﷺ would, on occasion, engage in gentle and wholesome humour.<br>This compilation presents a collection of humorous anecdotes drawn from classical Arabic works.</strong></p> <p><strong>ʿAlī ibn Abī Ṭālib (raḍiyallāhu ʿanhu) said:</strong><br><em>“Refresh your hearts and engage in some light-hearted wit, for hearts become weary just as bodies do.”</em></p> <p><strong>Ibn al-Jawzī (raḥimahullāh) stated:</strong><br><em>“The scholars have always shown an interest in light-hearted humour, lifting the spirits of others, for humour soothes the soul and relieves the heart of its burdens.”</em></p>', 450, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (94, 'humorous-anecdotes-from-the-lighter-side-of-islamic-history-volume-1', 'humorous-anecdotes-from-the-lighter-side-of-islamic-history-volume-1', 869, 'Humorous Anecdotes From the lighter side of Islamic History Volume 1', NULL, '<p><strong>It is established through authentic ḥadīths that the Messenger of Allah ﷺ would, on occasion, engage in gentle and wholesome humour.<br>This compilation presents a collection of humorous anecdotes drawn from classical Arabic works.</strong></p> <p><strong>ʿAlī ibn Abī Ṭālib (raḍiyallāhu ʿanhu) said:</strong><br><em>“Refresh your hearts and engage in some light-hearted wit, for hearts become weary just as bodies do.”</em></p> <p><strong>Ibn al-Jawzī (raḥimahullāh) stated:</strong><br><em>“The scholars have always shown an interest in light-hearted humour, lifting the spirits of others, for humour soothes the soul and relieves the heart of its burdens.”</em></p>', 450, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (95, 'golden-stories-from-the-life-of-faatimah-radhi-allah-anha', 'golden-stoires-from-the-life-of-fatimah', 865, 'Golden Stories From The Life Of Faatimah Radhi Allah Anha', NULL, '<p>This book takes the reader on a journey through the remarkable life of this extraordinary woman. It presents accounts of her noble character, exceptional upbringing, prophetic guidance, and inspiring family values. The lessons drawn from her life are clearly highlighted, offering women today a model to aspire to and a path to emulate.</p>', 400, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (96, 'riyad-al-salihin-with-commentary-complete-set', 'riyad-al-salihin-with-commentary-complete-set', 862, 'Riyad al-Salihin [With Commentary] COMPLETE SET', NULL, '<p><strong>A Translation and Commentary of Imām al-Nawawī’s ― Riyād al-Ṣāliḥīn</strong><br>Includes the original Arabic text of each ḥadīth</p> <p>This English translation of Riyād al-Ṣāliḥīn presents Imām al-Nawawī’s celebrated collection in a clear and accessible format, offering Arabic text side-by-side with English rendering and comprehensive commentary. The commentary draws on a range of classical Arabic commentaries and traditional explanations, making the work valuable both for beginners and for advanced students seeking deeper insight.</p> <p>Riyād al-Ṣāliḥīn addresses every aspect of Islamic belief and conduct, covering a wide array of themes and life situations—including etiquette, manners, morals, supplications, beliefs, worship, social interactions, and more. Its hadiths are drawn from the six canonical collections: Ṣaḥīḥ al‑Bukhārī, Ṣaḥīḥ Muslim, Jāmiʿ at‑Tirmidhī, Sunan Abū Dāwūd, Sunan an‑Nasa’ī and Sunan Ibn Mājah. <strong>Commentaries consulted for this edition include:</strong></p> <ul> <li> <p>Dalīl al‑Fālihīn</p> </li> <li> <p>Nuzhat al‑Muttaqīn</p> </li> <li> <p>The commentary of Muhammad Ilyās Barabankawī</p> </li> <li> <p>The commentary of Muhammad ʿAlī Sabūnī</p> </li> <li> <p>Rawḍat al‑Ṣāliḥīn (Urdu commentary)</p> </li> </ul> <p>This edition, available in a high-quality two-colour print, makes Riyād al-Ṣāliḥīn accessible to a broad readership—serving both as a reference for daily reading and a comprehensive guide for moral and spiritual development.</p>', 5300, 0, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (97, 'the-art-of-cultivating-noble-character', 'the-art-of-cultivating-noble-character', 840, 'The Art of Cultivating Noble Character', NULL, '<p><strong>The Art of Cultivating Noble Character</strong></p> <p>Yasien Mohamed, Emeritus Professor of Arabic and Islamic Philosophy at the University of the Western Cape, brings the profound insights of Imam Ragib al-Isfahānī to the English-speaking world. <em>The Art of Cultivating Noble Character</em> offers a rich and contemplative journey into Islamic moral thought, making it ideal for philosophy students, seekers of spiritual growth, and anyone wishing to deepen their understanding of Islamic virtue ethics.</p> <p>Following a meticulous three-year review, this expertly translated edition, complete with a critical introduction, is now available. As a seminal influence on thinkers such as Imām Ghazālī, Isfahānī’s masterpiece continues to provide timeless guidance on life’s most pressing moral questions.</p>', 1700, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (98, 'imam-sha-ranis-code-of-companionship', 'imam-sharanis-code-of-companionship', 836, 'Imam Sha‘rani’s Code of Companionship', NULL, '<p>Divided into four compelling sections, this work explores the essence of:</p> <ol> <li> <p>Embracing companionship for the sake of Allāh,</p> </li> <li> <p>Navigating the intricacies of true companionship rights,</p> </li> <li> <p>Upholding the noble etiquette of the righteous, and</p> </li> <li> <p>Imbibing the beauty of Allāh’s remembrance (<em>adhkār</em>).</p> </li> </ol> <p>This intricate tapestry of knowledge is masterfully woven, enlivening the heart and enriching the mind with insights that encourage the reader to discard blameworthy traits and cultivate the praiseworthy virtues exemplified by the pious.</p> <p>This profound text is ideally suited for study and reflection by imāms with their congregations, teachers with their students, parents with their children, and within academic institutions worldwide. Its timeless teachings have the power to elevate conduct, allowing the mercy of the Prophet (Sallallāhu ‘alayhi wa-sallam) to permeate our hearts. By internalizing these lessons and embodying them in our actions, we can extend this mercy to others, contributing to the restoration of humanity’s innate dignity and compassion in the world.</p>', 900, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (99, 'the-supreme-daily-remembrance-al-hizb-al-azam', 'the-supreme-daily-remembrance-illuminated-edition-al-hizb-al-azam', 832, 'The Supreme Daily Remembrance [Al-Hizb Al-Azam]', NULL, '<p><strong>The Supreme Daily Remembrance (Al-Ḥizb al-A‘ẓam) – Bilingual Edition</strong></p> <p>Although several illuminated manuscripts of <em>Al-Ḥizb al-A‘ẓam</em> exist, no fully illuminated printed edition had been available until White Thread Press published one in 2015. For a book of prayers of such significance, illumination adds aesthetic beauty and enhances the reader’s spiritual engagement.</p> <p><strong>The English Translation </strong><br>Since the original Arabic edition, public recitals (<em>maqra’āt</em>) of the full collection have been held worldwide, often followed by authorization ceremonies (<em>ijāzah</em>) for attendees. These gatherings inspired many to become regular readers of the book. Responding to demand, White Thread Press now presents a <strong>bilingual edition</strong>, with the Arabic text and facing English translation in a clear, visually appealing format.</p> <p>No effort has been spared to create an edition that brings immense joy and facilitates devotion.</p> <p><strong>Features of this edition include:</strong></p> <ul> <li> <p><strong>Arabic Typeface:</strong> Adapted from the original <em>naskh</em> script of the renowned Syrian calligrapher ‘Uthmān Ṭahā,** whose legible and elegant hand also prepared the Madīnah Mushaf read worldwide.</p> </li> <li> <p><strong>Layout:</strong> Twelve lines of Arabic per page with corresponding English translation, enclosed in a decorative gold-and-red frame.</p> </li> <li> <p><strong>Printing &amp; Design:</strong> Five-color printing on coated, varnished stock; sewn pages for durability; bound to lie flat for easy reading.</p> </li> <li> <p><strong>Illumination &amp; Ornamentation:</strong> Gold and colored headpieces mark the introduction and first section; section titles are enclosed in embellished borders. The ninety-nine Names of Allāh are featured across two double-page spreads. Ornaments indicate verse endings, and commas suggest pauses suited to the meaning, rhythm, and rhyme of invocations.</p> </li> <li> <p><strong>Typography &amp; Navigation:</strong> Classical Arabic manuscript style with modern typographical touches, including page numbers and marginal section heads with numerals for easy navigation. Halfway markers help divide each of the seven sections for multi-day completion.</p> </li> <li> <p><strong>Translation:</strong> The English text is concise, lucid, and faithful to the eloquence of the Arabic, avoiding unnecessary words or expressions.</p> </li> <li> <p><strong>Textual Basis:</strong> Primarily based on Indian editions, compared and emended with manuscripts from around the world to ensure accuracy. Sections from Saturday to Tuesday follow most manuscripts, while remaining sections follow the Indian editions.</p> </li> <li> <p><strong>References &amp; Appendices:</strong> Full references for invocations, a bibliography of print and manuscript sources, and an updated <em>ijāzah</em> for the author.</p> </li> <li> <p><strong>Deluxe Binding &amp; Finishing:</strong> Front and back covers feature the book title in gold foil with a central medallion and the author’s name; a debossed frame and arabesque pattern highlight the spine; ribbon marker included; gold gilding on page edges.</p> </li> </ul> <p><strong>Available in three faux leather covers:</strong></p> <ul> <li> <p>Rustic Red</p> </li> <li> <p>Rustic Blue</p> </li> <li> <p>Textured Brown</p> </li> </ul> <p>This deluxe edition combines beauty, durability, and spiritual functionality, making it ideal for daily devotion and study.</p>', 1800, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (100, 'imam-abu-hanifas-al-fiqh-al-akbar-explained', 'imam-abu-hanifas-al-fiqh-al-akbar-explained', 827, 'Imam Abu Hanifa’s Al-Fiqh al-Akbar Explained', NULL, '<p><strong>Imām Abū Ḥanīfah’s <em>Al-Fiqh al-Akbar</em> Explained</strong><br><em>By Abū ’l-Muntahā al-Maghnīsawī, with Selections from MullaʿAlī al-Qārī’s Commentary, including Abū Ḥanīfah’s Kitāb al-Wasiyyah</em>*</p> <p><em>Al-Fiqh al-Akbar</em> is one of the earliest surviving works on Islamic creed (<em>ʿaqīdah</em>) and one of the foundational texts of Imām Abū Ḥanīfah, the eminent jurist and theologian. Studied for centuries across the Muslim world, this text offers a nuanced and layered understanding of Tawḥīd (divine oneness), the central tenet of Islamic belief. It sharpens comprehension of the Creator, the Prophets, and divine revelation, while providing insight into the realities of this life and the hereafter.</p> <p>Beyond deepening one’s understanding of <em>ʿaqīdah</em> and nurturing spiritual conviction, <em>Al-Fiqh al-Akbar</em> addresses fundamental questions that, if left unresolved, could foster doubt or division within the community. Such questions include: Where is Allāh? Does Allāh undergo change? What constitutes true Islamic belief? Are Prophets capable of sinning? Does creation extend beyond what we perceive? What follows after death?</p> <p>This English translation represents an unprecedented contribution to the study of Islamic creed. Rendered clearly and accessibly, it avoids overly literal or rigid translation, drawing on multiple commentaries to make a subject previously inaccessible to many English readers both intelligible and engaging. By combining Abū ’l-Muntahā al-Maghnīsawī’s commentary with extensive notes selected from ʿAlī al-Qārī’s super-commentary, and incorporating Abū Ḥanīfah’s complete <em>Kitāb al-Wasiyyah</em>, this edition serves as an essential guide for anyone undertaking an intellectual and rewarding journey through Islamic theology.</p>', 1200, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (101, 'reflections-of-pearls', 'reflections-of-pearls', 822, 'Reflections Of Pearls', NULL, '<p><strong>Reflections of Pearls – A Concise &amp; Comprehensive Collection of Prophetic Invocations and Prayers</strong></p> <p>Allāh, Most High, says: <em>“Remember Me, and I will remember you.”</em> (Qur’ān 40:60)</p> <p>Calling out to Allāh brings a profound sense of belonging, protection, and inner peace. When combined with the powerful methods of supplication (<em>du‘ā’</em>) and remembrance (<em>dhikr</em>), this practice instills tranquility in the heart and mind. With this objective, Muslim scholars have compiled numerous collections of supplications and remembrances derived from the Qur’ān and the Prophetic Sunnah.</p> <p><em>Reflections of Pearls</em>, now in its third edition, is a concise compilation of Arabic supplications with English translations and transliterations. The book also includes sections on the etiquettes of supplication, the 99 Names of Allāh, selected blessings on the Messenger of Allāh (Sallallāhu ‘alayhi wa-sallam), the virtues of specific chapters and verses of the Qur’ān, and guidance on performing Istikhārah, Ishrāq, and other optional prayers. Both adults and children will benefit from and enjoy reading this work.</p> <p>The supplications are carefully selected for ease of learning. Arabic text is presented in clear Arabic script, English translations are lucid and accessible, and transliterations are provided in an easy-to-read format.</p>', 450, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (102, 'the-book-of-wisdoms-kitab-al-hikam', 'the-book-of-wisdoms-kitab-al-hikam', 818, 'The Book Of Wisdoms [Kitab al-Hikam]', NULL, '<p><strong>The Book of Wisdoms [<em>Kitāb al-Ḥikam</em> with <em>Ikmāl al-Shiyām</em>] – A Collection of Sufi Aphorisms with Commentary</strong></p> <p>Muslim religious life encompasses not only adherence to orthodox beliefs and diligent observance of the Sharī‘ah, but also the pursuit of spiritual refinement—attaining the states of the heart prescribed by the Islamic revelation.</p> <p>The <em>Kitāb al-Ḥikam</em> of Shaykh Ibn ʿAṭā’illāh al-Iskandarī (d. 1309) is a renowned and widely respected guide to the journey of Islamic spirituality, commonly referred to as “the Path” or “the Way,” with the Qur’ān and Sunnah as the ultimate arbiters of its principles. While the work includes treatises and supplications, its essence lies in a collection of <strong>264 spiritual aphorisms</strong>, which form the core of this edition. The aphorisms are presented according to the arrangement of the eminent Indian scholar Shaykh ʿAlī al-Muttaqī (d. 1567), accompanied by a commentary from the twentieth-century sage Shaykh ʿAbdullāh Gangohī.</p> <p>Shaykh Ibn ʿAṭā’illāh lived in Egypt during the Mamlūk era. Originally from Alexandria, he later moved to Cairo, where he taught the Sacred Law in various institutions, including al-Azhar Mosque. Simultaneously, he served as a spiritual guide, mentoring disciples along the Path. The <em>Ḥikam</em> is his principal work, widely revered from his own time to the present.</p> <p>Shaykh ʿAbdullāh Gangohī (d. 1921) taught in numerous Islamic schools across the Indian subcontinent during a period of significant academic and spiritual achievement. An expert in the Arabic language, many of his works are incorporated into the core curriculum of Islamic studies. He received spiritual guidance from the renowned ḥadīth scholar and Sufi Master Shaykh Khalīl Aḥmad Sahāranpūrī, who authorized him as a Master of the Path in his own right.</p>', 1600, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (103, 'ascent-to-felicity', 'ascent-to-felicity', 815, 'Ascent to Felicity', NULL, '<p><strong>Ascent to Felicity</strong></p> <p>Written by the eminent 11th-century Ḥanafī scholar, Abū ’l-Ikhlāṣ al-Shurunbulālī, <em>Ascent to Felicity</em> is a concise yet comprehensive primer on ʿaqīdah (creed) and fiqh (jurisprudence). The text covers all five pillars of Islām, as well as topics such as slaughtering, ritual sacrifice, and hunting.</p> <p>To enhance understanding, the translator has provided key explanatory notes drawn from several reliable works on theology and jurisprudence. Appendices include numerous supplications related to the five pillars, presented in <strong>Arabic script with English transliteration</strong>, as well as guidance on the etiquette of visiting the Messenger of Allāh (Sallallāhu ‘alayhi wa-sallam) in Madīnah.</p> <p><strong>By Abū ’l-Ikhlāṣ al-Shurunbulālī</strong> (author of <em>Nūr al-Idāh</em>).<br><strong>Translation, notes, and appendices by Faraz A. Khan.</strong></p>', 900, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (104, 'imam-ghazali-the-beginning-of-guidance', 'imam-ghazali-the-beginning-of-guidance', 812, 'Imam Ghazali: The Beginning of Guidance', NULL, '<p><strong>Imām Ghazālī’s <em>Bidayat al-Hidāyah</em></strong></p> <p><em>Bidayat al-Hidāyah</em> is a profoundly motivational manual that presents the fundamentals of attaining guidance through <em>taqwā</em>. Imām Ghazālī emphasizes that, just as there is an ultimate goal in this noble pursuit, there is also a beginning—which must be firmly established in order to achieve true success. He then elaborates on the essential principles of this “beginning.”</p> <p>While concise and to the point, the manual is structured in the form of a detailed daily timetable, offering the reader both strong inspiration and heartfelt counsel. The book is divided into three sections: obedience to Allāh, refraining from disobedience, and the proper etiquette of companionship with the Creator and with creation.</p> <p>As one of Imām Ghazālī’s final works, <em>Bidayat al-Hidāyah</em> reflects a lifetime of learning, experience, and spirituality. It also serves as an accessible introduction to his broader corpus of works.</p> <p>This edition, published for the first time with Arabic text, includes transliteration and explanatory notes for the supplications contained within.</p>', 700, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (105, 'provisions-for-the-seekers', 'provisions-for-the-seekers', 809, 'Provisions for the Seekers', NULL, '<p><strong>A Manual of Prophetic Ḥadīths with Commentary</strong></p> <p><strong>A Translation &amp; Commentary of Shaykh Ashiq Ilāhī al-Bulandshehrī&#8217;s <em>Zad al-Ṭālibīn</em></strong><br>Includes the original Arabic text.</p> <p>Imām Nawawī famously stated: <em>“The science of ḥadīth is the noblest means of attaining closeness to the Lord of the Worlds.”</em></p> <p>The Messenger of Allāh (Sallallāhu ‘alayhi wa-sallam) possessed extraordinary oratorical skills. His words were eloquent, profound, and simple, conveying boundless wisdom and guidance in a few words. He himself said: <em>“I have been sent with the jawāmi‘ al-kalim”</em> (Bukhārī)—succinct expressions that communicate a multitude of meanings.</p> <p>Today, bookstores and libraries are filled with collections of proverbs and sayings attributed to historical figures, political leaders, and philosophers. Yet all of these pale in comparison to the eloquence and divine wisdom of the Prophet Muḥammad (Sallallāhu ‘alayhi wa-sallam). In the light of his guidance, the wisest philosophers and sages appear as mere students.</p> <p>This book presents a carefully curated collection of <strong>327 ḥadīths</strong>, compiled by Shaykh Ashiq Ilāhī al-Bulandshehrī from ‘Allāma Tabrīzī’s renowned work <em>Mishkāt al-Masābīḥ</em>. It includes many examples of <em>jawāmi‘ al-kalim</em>, as well as prophecies, narratives, and other instructive accounts.</p> <p>Designed to inspire the hearts and minds of today’s Muslims, this collection offers a glimpse into the charisma of the Prophet (Sallallāhu ‘alayhi wa-sallam) and provides practical guidance for those seeking closeness to Allāh.</p> <p>Widely taught in madāris around the world as an introductory ḥadīth text, this beautifully bound English edition now makes Shaykh Ashiq Ilāhī al-Bulandshehrī’s work accessible, complete with commentary from classical sources.</p>', 700, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (106, 'saviours-of-islamic-spirit', 'saviours-of-islamic-spirit', 798, 'Saviours of Islamic Spirit', NULL, '<p><strong>Saviours of Islamic Spirit</strong><br><em>Tarīkh-i Daʿwat wa ʿAzīmat</em> by Abū ’l-Ḥasan ʿAlī al-Ḥasanī Nadwī<br>A New Revised and Edited Translation<br>Revised and Edited by Abdur-Rahman ibn Yusuf Mangera</p> <p>This masterful work by the late Indian historian and intellectual, Shaykh Abū ’l-Ḥasan ʿAlī Nadwī, recounts the rises and declines of the Muslim Ummah—its trials, setbacks, and, most significantly, its victories. It is a moving chronicle of the achievements and triumphs that propelled the Ummah forward. The narrative unfolds through the lives of extraordinary individuals: revivers endowed with courage, resolve, and zeal—an elect group divinely inspired to preserve the spirit of God’s religion on earth. They were, in essence, the saviours of the Islamic spirit.</p> <p>Drawing upon the lives of ten of the most influential figures from the first seven centuries of Islam—from Ḥasan al-Baṣrī, ʿUmar ibn ʿAbd al-ʿAzīz, Aḥmad ibn Ḥanbal, and al-Ghazālī to Ibn al-Jawzī and Ṣalāḥ al-Dīn al-Ayyūbī—this work offers reassurance and essential perspective in light of the current challenges facing Muslims worldwide. It aims to inspire Muslim youth and all seekers of virtue to cultivate love for Allah and to adopt role models of intellectual and spiritual excellence at a time when many search for guidance in less deserving places. This history reminds us that our present circumstances are far from the darkest moments the Ummah has endured.</p> <p><strong>Personalities Covered</strong></p> <ul> <li> <p>Imam Ḥasan al-Baṣrī</p> </li> <li> <p>Imam ʿUmar ibn ʿAbd al-ʿAzīz</p> </li> <li> <p>Imam Aḥmad ibn Ḥanbal</p> </li> <li> <p>Imam Abū ’l-Ḥasan al-Ashʿarī</p> </li> <li> <p>Imam Abū Ḥāmid al-Ghazālī</p> </li> <li> <p>Imam ʿAbd al-Qādir al-Jīlānī</p> </li> <li> <p>Imam ʿIzz al-Dīn ibn ʿAbd al-Salām</p> </li> <li> <p>Imam Abū ’l-Faraj Ibn al-Jawzī</p> </li> <li> <p>Sultan Ṣalāḥ al-Dīn al-Ayyūbī</p> </li> <li> <p>Sultan Nūr al-Dīn Zangī</p> </li> <li> <p>The Tartars</p> </li> </ul> <p><strong>The Author</strong></p> <p>Shaykh Abū ’l-Ḥasan ʿAlī al-Ḥasanī Nadwī (1332/1914–1420/1999), affectionately known as ʿAlī Miyān, was one of the leading intellectuals and religious scholars of modern India. A prolific author, he wrote extensively on history, biography, and contemporary issues affecting Muslims in India and abroad. He served as rector of the renowned Nadwat al-ʿUlamāʾ seminary in Lucknow, where he taught Qur’anic exegesis, ḥadīth, Arabic literature, history, and logic.</p> <p>He was a founding member of <em>Rābiṭat al-Adab al-Islāmī al-ʿĀlamiyyah</em> (the Universal League of Islamic Literature) and later chaired the All-India Muslim Personal Law Board. His literary legacy spans hundreds of works in Arabic and Urdu, many of which have become part of university curricula across the Arab world. His celebrated Arabic treatise <em>Mādhā Khasira al-ʿĀlam bi Inḥiṭāṭ al-Muslimīn</em> (<em>What Did the World Lose by the Decline of the Muslims?</em>) secured his place among the foremost thinkers of the Muslim world.</p> <p>His major contributions include his eight-volume autobiography <em>Kārwān-i Zindagī</em>, <em>Purāne Chirāgh</em> (profiles of contemporary luminaries), biographies of Sayyid Aḥmad Shāhīd and Sayyidunā ʿAlī (may Allah ennoble his countenance), and his monumental <em>Tarīkh-i Daʿwat wa ʿAzīmat</em> (<em>Saviours of Islamic Spirit</em>). He passed away at the age of eighty-six on Friday, 31 December 1999 (22 Ramadan 1420).</p>', 1000, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (107, 'the-essentials-of-islamic-spirituality', 'the-essentials-of-islamic-spirituality', 795, 'The Essentials of Islamic Spirituality', NULL, '<p>Shaykh Masīḥullāh Khān Ṣāḥib, a distinguished student of the eminent Mawlānā Ashraf ʿAlī Thānavī, authored <em>Sharīʿat and Taṣawwuf</em> to convey to future generations the immense benefit of his teacher’s wisdom. The teachings collected in this work are heartfelt notes of counsel, admonition, and encouragement from a man who has traversed the path to his Creator. At their core, they offer nourishment for the spiritually weary hearts and souls of our time.</p> <p>White Thread Press has presented this invaluable text in elegant and evocative prose, while remaining faithful to its traditional essence. The result is a work that places a profound awakening of the heart within reach of every reader. Those new to the spiritual sciences will find delight in the breadth and depth of Islam’s psychological and spiritual disciplines, while those already journeying along the Path will discover fresh insights and renewed perspectives.</p> <p>In an age when discourse surrounding Islam is often shallow, superficial, or inauthentic, <em>The Path to Perfection</em> provides a long-awaited remedy. It not only identifies the spiritual maladies that plague us, but also offers concrete means for their cure—so that we, as individuals, communities, and as an Ummah, may benefit from a truly spiritual way of life.</p>', 500, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (108, 'fiqh-al-imam', 'fiqh-al-imam', 792, 'Fiqh al-Imam', NULL, '<p>The first part of this book aims to clarify key aspects of <em>taqlīd</em> that are often misunderstood or severely misrepresented. It highlights the necessity of <em>taqlīd</em>, traces its historical development, and explains its continued relevance and importance in the modern world.</p> <p>The second part consists of several chapters dedicated to issues of <em>ṣalāh</em> (ritual prayer) according to the Hanafi school. Through clear examples and detailed analyses, these chapters demonstrate the sophisticated legal reasoning employed by the Hanafi madhhab—indeed, by all the established madhhabs—in deriving legal rulings from the primary textual sources of Islam. Every ruling presented is supported by evidentiary proofs from the Qur’an and Hadith.</p> <p>Throughout the work, the author maintains a balanced and impartial tone. His purpose is not to provoke controversy or fuel polemics, but to present the facts in a lucid, rational, and accessible manner—appealing to the reader’s sense of reason while illuminating the depth and coherence of the Islamic legal tradition.</p>', 500, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (109, 'the-absolute-essentials-of-islam', 'the-absolute-essentials-of-islam', 789, 'The Absolute Essentials of Islam', NULL, '<p><strong>A Basic Hanafi Primer on Faith, Prayer, &amp; the Path of Salvation</strong>, compiled by Shaykh Faraz Rabbani and based on Shaykh Amin Jundi’s <em>Iṣlāḥ ‘Ilm al-Ḥāl</em>, presents the essential knowledge every Muslim needs in order to worship Allah correctly and meaningfully. Allah Most High commands us to worship Him with sincerity, gratitude, and reverence, as He says in the Qur’an: <em>“And they were commanded only to worship Allah, devoting religion purely to Him, remaining steadfast, and establishing prayer and giving zakat—that is the true religion.”</em> (Qur’an 98:5)</p> <p>Sound worship is not possible without sound knowledge. This concise primer distils the fundamental matters of faith (‘aqīdah), prayer (ṣalāh), and key aspects of daily life and conduct that every Muslim is required to know. Accessible and practical, it helps the reader gain the necessary understanding to ensure that their acts of devotion are valid, proper, and pleasing to Allah.</p> <p>Rooted in the methodology of traditional Sunni Islam and based on the Hanafi school—the largest and one of the most rigorously developed schools of Islamic law—this work is designed to provide a reliable foundation in a short amount of time. It is an ideal starting point for beginners and a valuable refresher for anyone seeking clarity in the essentials of their religious practice.</p>', 300, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (110, 'differences-of-the-imams', 'differences-of-the-imams', 786, 'Differences Of The Imams', NULL, '<p>English Translation of Hadhrat Shaykh Muhammad Zakariyya&#8217;s &#8216;Ikhtilaaf al-A&#8217;immah&#8217;</p>', 300, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (111, 'handbook-of-a-healthy-muslim-marriage', 'handbook-of-a-healthy-muslim-marriage', 782, 'Handbook of a Healthy Muslim Marriage', NULL, '<p><strong>The Handbook of a Healthy Muslim Marriage</strong> is an indispensable guide for every Muslim seeking clarity, confidence, and harmony in marriage. With deep insight and a warm, empathetic tone, Shaykh Abdur-Rahman ibn Yusuf Mangera draws upon thousands of hours of spiritual guidance, marital counselling, and rich Islamic scholarship to address one of life’s most important journeys. The book covers everything from finding a suitable spouse and managing in-law dynamics to nurturing emotional and physical intimacy, as well as navigating the painful realities of marital breakdown when necessary.</p> <p>Written with exceptional clarity and accessibility, this guide is both thoughtful and engaging. It offers a wealth of real-life anecdotes, cultural observations, and relevant legal discussions, making it especially relatable to Western readers. Practical solutions are presented for common marital challenges, including communication breakdown, conflict resolution, and unmet expectations. Sensitive issues such as domestic violence, infertility, and sexual intimacy are handled with care and candour. It also provides valuable tips for cultivating romance and sustaining affection throughout the marriage.</p> <p>This handbook is a vital resource for couples at every stage—newlyweds, long-married partners, and even those preparing for marriage. It has the potential to prevent serious marital mistakes, heal strained relationships, and guide couples toward a fulfilling and spiritually grounded union. It stands as one of the finest contemporary Islamic self-help works on marriage available today.</p>', 900, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (112, 'in-the-presence-of-the-beloved', 'in-the-presence-of-the-beloved', 768, 'In the Presence of the Beloved', NULL, '<p><em>In the Presence of the Beloved</em> presents an eloquent translation of two authoritative treatises on the practice of <em>ziyārah</em>—visiting the Prophet Muhammad Sallahu alayhi Wasalam. Both works offer a detailed study of the ruling, immense virtues, and proper etiquettes associated with this sacred act. They also thoughtfully address a range of related issues, including those that have become points of contention in modern discourse, such as the permissibility of <em>tawassul</em> (supplicating to Allah through the Prophet), <em>tabarruk</em> (seeking blessings through his relics), the unique virtues of the Rawḍah and Madinah, and the importance of visiting other revered historical landmarks in the Prophet’s city.</p>', 900, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (113, 'a-commentary-of-jami-at-tirmidhi-chapters-of-the-adhan', 'a-commentary-of-jami-at-tirmidhi-chapters-of-the-adhan', 750, 'A Commentary of Jami At- Tirmidhi: Chapters of the Adhan', NULL, '<p>One of the most iconic symbols of Islam, the <em>adhān</em>—the call to Ṣalāh—is instantly recognisable to Muslims and non-Muslims alike across the world. For the first time, this subject is explored in all its nuance and depth through the lens of Imām Muḥammad ibn ʿĪsā al-Tirmidhī’s <em>Sunan</em>, complete with the original Arabic text and translation.</p> <p>The many legal and theological issues related to the <em>adhān</em> are examined using the classical disciplines of ḥadīth, jurisprudence, and Qur’ānic exegesis. In doing so, the work not only highlights the enduring importance and relevance of the <em>adhān</em> itself, but also showcases Imām al-Tirmidhī’s distinctive pedagogical method.</p>', 800, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (114, 'an-introduction-to-mishkat-al-masabih', 'an-introduction-to-mishkat-al-masabih', 747, 'An Introduction to Mishkat al-Masabih', NULL, '<p><em>Mishkāt al-Maṣābīḥ</em> is a comprehensive collection of hadith that addresses virtually every aspect of Islamic belief, jurisprudence (fiqh), and moral virtues. It is widely taught to students of Hadith across the world, especially in the madrasahs of the Indian subcontinent, South Africa, the United Kingdom, and the United States. In many traditional curricula, <em>Mishkāt al-Maṣābīḥ</em> serves as an essential preparatory text studied before progressing to <em>al-Kutub al-Sittah</em> (the Six Canonical Books of Hadith).</p>', 500, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (115, 'towards-understanding-hadith-exploring-ten-key-issues', 'towards-understanding-hadith-exploring-ten-key-issues', 740, 'Towards Understanding Hadith Exploring Ten Key Issues', NULL, '<p>In 1291/1875, during his stay in Hyderabad Deccan, Imam al-Laknawī responded to ten questions concerning the hadith sciences posed by the Ahl-e-Hadith scholar ʿAllāmah Muḥammad Ḥusayn al-Lāhawrī, which resulted in this indispensable work. The text emphasises the importance of the chain of narration (isnād) in all religious matters and discusses weak hadiths, their conditions, and implementation.</p> <p>It also examines various collections of hadith and Qur’ānic exegesis, evaluating the reliability and authority of the narrations they contain. The work provides a clear framework for reconciling differing scholarly assessments of hadith authenticity and narrator reliability, and it offers practical guidance on managing seemingly conflicting hadith texts. Furthermore, it discusses the legal implications when a Companion does not act upon a hadith he himself transmits, and it addresses cases in which a Companion’s statement or action appears to conflict with a Prophetic narration. The value of the work is further enriched by the extensive annotations of Shaykh ʿAbd al-Fattāḥ Abū Ghuddah. It stands as an indispensable resource for anyone engaging with hadith literature, filling an important gap in English-language scholarship on these essential topics.</p>', 700, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (116, 'qawaid-al-aqaid-the-foundation-of-belief', 'qawaid-al-aqaid-the-foundation-of-belief', 734, 'Qawaid al-Aqaid : The Foundation of Belief', NULL, '<p>Its clarity and brevity have made this text a favourite for teaching and learning since the time it was written. One commentary that remains relatively unknown to English readers is <em>Ightinām al-Fawā’id fī Sharḥ Qawaʿid al-ʿAqa’id</em>, authored by the 15th-century Shādhilī Ṣūfī reformer of Morocco, Sīdī Aḥmad Zarrūq (d. 899/1493). Distinguished by its descriptive clarity and accessible style, it serves as an excellent guide for readers seeking a firm grounding in the key terms, concepts, and arguments of orthodox Sunnī Islamic theology.</p>', 600, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (117, 'qadi-iyads-shifa-abridged', 'qadi-iyads-shifa-abridged', 730, 'Qadi Iyad’s Shifa Abridged', NULL, '<p>Written nearly nine centuries ago, this masterpiece has long been embraced by the ummah as one of the greatest tributes to the Prophet Muhammad ﷺ. It outlines the essential beliefs concerning the Prophet ﷺ, illuminates his metaphysical and physical perfections, and details the rights and responsibilities owed to him by his followers. As the original work is extensive, we are pleased to present this accessible English abridgement for today’s readers.</p>', 700, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (118, 'a-muslims-guide-to-modernity', 'a-muslims-guide-to-modernity', 726, 'A Muslim’s Guide to Modernity', NULL, '<p>This book presents a thoughtful collection of essays exploring Islam’s relevance in an ever-changing modern world. Authored by Shaykh Surkheel Sharif (Abu Aaliyah), each essay offers clear guidance for Muslims striving to navigate contemporary challenges while remaining faithful to their religious principles. By harmonising tradition with present-day realities, these concise yet profound reflections provide a practical roadmap through questions of reason, identity, spirituality, and social responsibility.</p>', 1400, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (119, 'the-muwatta-of-imam-muhammad', 'the-muwatta-of-imam-muhammad', 722, 'The Muwatta of Imam Muhammad', NULL, '<p><strong>The Muwatta of Imām Muḥammad</strong></p> <p><em>“The unqualified truth is that all of the Muwatta is ṣaḥīḥ without any exception!”</em><br>— Ḥāfiẓ Ibn Ḥajar al-ʿAsqalānī</p> <p>A testimony of this magnitude—coming from one of the greatest ḥadīth authorities in Islamic history—is sufficient recommendation in itself. The recension of the <em>Muwattaʾ</em> narrated by Imām Muḥammad ibn al-Ḥasan al-Shaybānī, one of the foremost students of Imām Abū Ḥanīfah, is especially valuable. Drawn from his three years of direct study with Imām Mālik, it holds particular significance not only for students of Ḥanafī jurisprudence but also for serious students of ḥadīth more broadly.</p> <h3><strong>The Muwattaʾ</strong></h3> <p>Imām Mālik compiled the <em>Muwattaʾ</em> over forty years to capture the “well-trodden path” (<em>al-ṭarīq al-muwattaʾ</em>) of the people of Madinah. Its title also carries the meaning of a text “agreed upon repeatedly”—a book whose contents reflected the consensus and lived practice of Madinah and which was made clear and accessible.</p> <p>Its lofty status is universally acknowledged: scholars of every school of fiqh and all major imams of ḥadīth agree on its exceptional authenticity. Imām al-Shāfiʿī stated: <em>“There is no book on the face of the earth—after the Book of Allah—more authentic than the book of Mālik.”</em> Shah Walī Allāh al-Dihlawī (1114–1176 AH) similarly affirmed, <em>“My heart opened, and I became convinced that the Muwattaʾ is the most authentic book on earth after the Book of Allah.”</em></p> <h3><strong>Imām Mālik</strong></h3> <p>Imām Mālik—leader of the scholars of Madinah and “the scholar of the scholars”—was Mālik ibn Anas ibn Mālik ibn Abī ʿĀmir al-Aṣbaḥī al-Madanī. Born in 94, 95, or 99 AH, he was widely recognised as the “Man of Knowledge of Madinah,” whom many early scholars believed the Prophet ﷺ referred to in the ḥadīth of Abū Hurayrah:<br><em>“People will travel far in search of knowledge, but they will not find anyone more knowledgeable than the scholar of Madinah.”</em></p> <p>Among his distinguished students were Sufyān al-Thawrī; Saʿīd ibn Manṣūr; ʿAbdullāh ibn al-Mubārak; al-Awzāʿī; Layth ibn Saʿd; Imām al-Shāfiʿī; Muḥammad ibn al-Ḥasan al-Shaybānī; and leading Mālikīs such as Ibn al-Qāsim, Yaḥyā ibn Yaḥyā al-Laythī, Ibn Wahb, and Dhū al-Nūn al-Miṣrī. Imām Mālik passed away in 179 AH on the morning of the 14th of Rabīʿ al-Awwal.</p> <h3><strong>Imām Muḥammad al-Shaybānī</strong></h3> <p>Abū ʿAbdullāh Muḥammad ibn al-Ḥasan ibn Farqad al-Shaybānī was born in Wāsiṭ in 132 AH and raised in Kufa. A direct disciple of Imām Abū Ḥanīfah, he later became one of the principal architects of the Ḥanafī school. Imām al-Shāfiʿī said of him: <em>“I have never seen anyone more eloquent than him; when he recited the Qurʾān, it was as though the Qurʾān had been revealed in his language.”</em> He also stated, <em>“I have not seen anyone more intelligent than Muḥammad ibn al-Ḥasan.”</em></p> <p>Al-Dhahabī described him as <em>“an ocean of knowledge and jurisprudence,”</em> noting his precision in narrating from Imām Mālik. Imām Muḥammad himself said: <em>“I stood at the door of Mālik for three years and heard the Muwattaʾ from him—over seven hundred ḥadīth.”</em> He passed away in Rayy in 189 AH.</p>', 1300, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (120, 'an-ocean-of-tears', 'an-ocean-of-tears', 719, 'An Ocean of Tears', NULL, '<p>Imam ʿAbd ar-Raḥmān ibn ʿAlī al-Jawzī, widely known as Ibn al-Jawzī, stands out as a rare scholar who combined rigorous academic mastery with a profound concern for the spiritual well-being of the Muslim community. Renowned for his vast knowledge, he was also an extraordinary orator whose sermons moved hundreds of thousands to repentance over the course of his remarkable life. Born in 518 AH and passing away nearly eight decades later in 597 AH, he left behind a rich legacy of influential works in ḥadīth, tafsīr, and moral exhortation (waʿẓ) — one of which is the very work now before you.</p>', 600, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (121, 'haramayn-guide-series-al-madinah-al-munawwarah', 'haramayn-guide-series-al-madinah-al-munawwarah', 712, 'Haramayn Guide Series – Al-Madinah Al-Munawwarah', NULL, '<p>Embark on an extraordinary journey through the heart of Madinah with this comprehensive guide. Discover over 100 remarkable sites, each carefully detailed with exact coordinates and QR codes, ensuring that your pilgrimage is both seamless and unforgettable.</p>', 1100, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (122, 'living-wisely-teachings-of-imam-mawardi-on-ethics-and-human-wellbeing', 'living-wisely-teachings-of-imam-mawardi-on-ethics-and-human-wellbeing', 707, 'Living Wisely – Teachings of Imam Mawardi on Ethics and Human Wellbeing', NULL, '<p>In his introduction, <strong>Imam al-Māwardī</strong> writes:</p> <blockquote> <p>“In this book, I aim to provide a guide to the wisdom necessary for attaining felicity in both the spiritual and worldly realms. I have sought a middle path between brevity and lengthy disquisitions, balancing the precision of scholarly discourse with the emotional refinement of literature. Nothing herein is so difficult as to be beyond understanding, nor so subtle as to elude visualisation.</p> </blockquote> <blockquote> <p>I have grounded my work in the Quran and the exalted example of His Messenger ﷺ. Beyond this, I have drawn upon the sayings of sages, the aphorisms of masters of rhetoric, and the verses of poets, for the human spirit finds comfort in variety and grows weary of monotony.”</p> </blockquote>', 1300, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (123, 'jami-at-tirmidhi-chapters-on-trade-and-commerce-explained', 'jami-at-tirmidhi-chapters-on-trade-and-commerce-explained', 703, 'Jami at-Tirmidhi: Chapters on Trade and Commerce Explained', NULL, '<p>Turath Publishing is proud to present its readers with a translation of this monumental work. This edition focuses specifically on the chapters concerning trade and commerce. Alongside a clear and highly readable translation, the translator has included valuable footnotes drawn from Mufti Muhammad Taqi Usmani’s other works, making it a comprehensive manual on Islamic finance. It is an essential resource for Islamic scholars, students, and professionals in the Islamic finance industry alike.</p>', 900, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (124, 'women-of-excellence-in-the-time-of-the-prophet', 'women-of-excellence-in-the-time-of-the-prophet-%ef%b7%ba', 698, 'Women of Excellence – In the time of the Prophet', 'ﷺ', '<p>The guidance of the Prophet ﷺ was the ultimate priority in their lives, taking precedence over personal health, wealth, and even life itself. They lived as travellers in this world, ever mindful of their journey toward a glorious eternal abode.</p> <p>These pages are filled with timeless lessons for anyone striving to follow the straight path, inviting profound spiritual reflection on our own relationships with Allah and His Messenger ﷺ.</p>', 1200, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (125, 'stories-of-the-prophets-2', 'stories-of-the-prophets', 693, 'Stories of the Prophets', NULL, '<p>Qasas al-Anbiya, extracted from the celebrated Imam Ibn Kathīr’s <em>al-Bidāyah wa’n-Nihāyah</em>, offers a detailed exploration of the rich and instructive lives of the Prophets, peace and blessings be upon them all. This timeless work aims to reconnect Muslims with the Qur’anic narratives and the exemplary conduct of the Prophets.</p> <p>In this book, Ibn Kathīr presents Qur’anic verses accompanied by authentic narrations of the Final Prophet ﷺ, while also consulting earlier scriptures with careful scrutiny regarding their authenticity. May Allah Taala instill in us the noble qualities of the best of humankind and unite us with them in <em>Firdaus al-A‘lā</em>. Āmīn.</p>', 900, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (126, 'bidayat-as-sul-fi-tafdil-ar-rasul', 'bidayat-as-sul-fi-tafdil-ar-rasul', 690, 'Bidayat as-Sul Fi Tafdil ar-Rasul', NULL, '<p>The Beginning of the Quest for the High Esteem of the Messenger Sallahu alayhi Wasalam</p> <p><em>Bidayat as-Sul fī Tafḍīl ar-Rasūl</em> (The Beginning of the Quest for the High Esteem of the Messenger) is a concise work that succinctly outlines forty distinctive virtues and characteristics of the Messenger of Allah (Allah bless him and give him peace).</p> <p>The author, Imām ʿIzz ibn ʿAbd al-Salām, known as the <em>Sultan of Scholars</em>, produced numerous brilliant works across a range of disciplines, including Shāfiʿī jurisprudence, Qur’ānic exegesis, the methodological fundamentals of sacred law, formal legal opinion (<em>fatwā</em>), governance, and Sufism. Among his masterpieces is <em>Qawāʿid al-Aḥkām fī Maṣāliḥ al-Anām</em> (The Bases of Legal Rulings in the Interests of Mankind), which remains a foundational reference in Islamic legal theory.</p>', 220, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (127, 'be-mindful-of-allah', 'be-mindful-of-allah', 688, 'Be Mindful of Allah', NULL, '<p>This book is a commentary on the invaluable advice of the Prophet ﷺ to ʿAbdullāh ibn ʿAbbās (Raḍiya ’llāhu ʿan-hu), beginning with the words: “Be mindful of Allah and He will be mindful of you.” The renowned eighth-century Imam Ibn Rajab al-Ḥanbalī guides the reader through a thoughtful exploration of the hadith’s meanings, presenting its lessons in a manner that is both scholarly and accessible. He demonstrates that the hadith “contains great counsel and comprehensive principles from the most important and significant aspects of the religion,” including the rights owed to Allah ﷻ and the rewards promised for fulfilling them.</p> <p>Ibn Rajab substantiates his commentary with Qur’anic verses, additional prophetic narrations (analyzed for authenticity), sayings of the Companions (Raḍiya ’llāhu ʿan-hum) and their successors, as well as illustrative stories and poetry. Offering a concise yet expansive examination of some of Islam’s core tenets, this work is an essential addition to every Muslim’s library.</p>', 450, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (128, 'naqsh-e-hayat-a-biography-and-memoirs-of-shaykh-hussain-ahmad-madani', 'naqsh-e-hayat-a-biography-and-memoirs-of-shaykh-hussain-ahmad-madani', 686, 'Naqsh e Hayat: A Biography and Memoirs of Shaykh Hussain Ahmad Madani', NULL, '<p> This book highlights the pivotal role of prominent individuals and institutions in the struggle to end British colonial rule in India. It traces the resistance movement beginning with the establishment of Darul-Uloom Deoband by Shaykh Qāsim Nānatwī and Shaykh Rashīd Aḥmad Gangohī following the 1857 British occupation of Delhi, and also examines the contributions of Shaykh Sayyid Aḥmad Shaheed and Shaykh al-Hind Maḥmūd Ḥasan . </p> <p>By documenting these efforts, the book not only acknowledges their significant contributions but also challenges nationalist and exclusivist historians who have overlooked the role of Muslims in India’s liberation struggle. It serves as a valuable resource for students and researchers in colleges, universities, and Darul Ulooms, and is equally beneficial for anyone seeking to understand the anti-colonial movement in India.</p>', 500, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (129, 'social-etiquette-adab-al-muasharat', 'social-etiquette-adab-al-muasharat', 683, 'Social Etiquette: Adab al-Mu’asharat', NULL, '<p>Social Etiquette (Ādāb al-Muʿāsharāt), authored by the eminent South Asian scholar Hakim al Ummah Mawlānā Ashraf ʿAlī Thānawī Sahib, is a concise yet profound treatise on cultivating and refining one’s social conduct. Drawing on personal experience, Mawlānā Thānawī offers anecdotes and practical examples, highlighting interactions and scenarios that may seem trivial or harmless but, in reality, contradict the spirit of Islam. While the work is easy to read, it calls for practical implementation—encouraging readers to elevate the standards of Islamic behavior in social life, foster healthy communities, and nurture peace, harmony, love, and cohesion.</p> <p>To make this translation accessible to the millions of Muslims living in Western countries, footnotes have been added (not present in the original text) offering examples and commentary relevant to contemporary contexts, helping readers apply the timeless guidance of Mawlānā Thānawī to the challenges and circumstances of modern life.</p>', 220, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (130, 'the-tradition-of-the-scholars-of-deoband', 'the-tradition-of-the-scholars-of-deoband', 678, 'The Tradition of the Scholars of Deoband', NULL, '<p>Over the past twenty years, global geopolitics have brought the Deoband movement and its scholars into prominent public attention. Understanding who the Deoband scholars are, what they believe, and their positions on various issues can be complex and confusing for journalists, academics, and even ordinary Muslims. With many attempting to grasp Deoband’s teachings in a fragmented or superficial way, Barbara Metcalf aptly observes that “the need to understand Deoband and other Islamic movements in their own terms…continues to be of great urgency in the plural, global world of today.” This English translation of <strong>Qāri Muḥammad Ṭayyab’s</strong> work, <em>Maslak Ulama-i-Deoband</em>, seeks to address this need by providing a clear and accessible explanation of the movement, its scholars, and its intellectual and religious positions.</p>', 320, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (131, 'khasail-commentary-of-shamaail', 'khasail-commentary-of-shamaail', 672, 'Khasa’il (Commentary of Shamaail)', NULL, '<p>Imam Tirmidhī’s <em>Ash-Shamā’il al-Muḥammadiyyah</em> is a distinguished compilation of ḥadīth that detail the noble features, exalted attributes, and exemplary qualities of the Messenger of Allah ﷺ. Over the centuries, numerous scholars have written commentaries on this work, and among them, the great ḥadīth scholar Shaykh al-Ḥadīth Mawlana Muḥammad Zakariyyā Kandhlawī Sahib produced an invaluable Urdu commentary titled <em>Khaṣā’il Nabawiyyah</em>—a work that continues to benefit both scholars and general readers alike.</p> <p>This English edition presents Imam Tirmidhī’s ḥadīth alongside Shaykh Zakariyyā’s insightful commentary, offering readers vivid portrayals of the Messenger of Allah ﷺ. Through clear, coherent, and accessible exposition, it illuminates his blessed lifestyle, perfect character, habits, manners, ethics, and acts of worship, providing both inspiration and guidance for those seeking to understand and emulate his exemplary way of life.</p>', 1700, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (132, 'softening-the-heart', 'softening-the-heart', 667, 'Softening The Heart', NULL, '<p>Imam ʿAbdullāh ibn al-Mubārak’s <em>Kitāb al-Zuhd wa’l-Raqā’iq</em>, the earliest surviving work on self-discipline in Islam, is a rich compilation of Qur’ānic commentary, prophetic traditions, and anecdotes from the pious early generations. Its aim is to guide readers toward renouncing the fleeting pleasures of this worldly life in favor of the eternal rewards of the Hereafter.</p> <p>This edition opens with comprehensive introductions on the concept of <em>zuhd</em>, highlighting its wide-ranging applications and enabling readers to appreciate the profound legacy of self-discipline among the early Muslims. Brimming with timeless wisdom and heartfelt guidance, the book offers priceless gems that soften hearts, cultivate the fear of Allah Taala, and inspire sincere hope and reliance upon Him.</p>', 1200, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (133, 'the-garden-of-the-hadith-scholars', 'the-garden-of-the-hadith-scholars', 664, 'The Garden Of The Hadith Scholars', NULL, '<p>Bustan al-Muḥaddithīn is a renowned anthology covering the sciences of ḥadīth, the major ḥadīth collections, and the great masters of the discipline. Written in Persian in the early nineteenth century by Shah ʿAbd al-ʿAzīz Dihlawī (1745–1822), it has long enjoyed exceptional popularity among Indian scholars of ḥadīth. In both scope and clarity, it surpasses many works authored on the same subject in Arabic, Persian, and other languages.</p> <p>Shah ʿAbd al-ʿAzīz Muḥaddith Dihlawī</p> <p>Born in Delhi in 1745, Shah ʿAbd al-ʿAzīz received his early education from his illustrious father, Shah Walī Allāh, as well as from his father’s distinguished students, Shah Muḥammad Āshiq and Mawlānā Khwāja Amīnullāh. He studied fiqh under his father-in-law, Mawlānā Nūrullāh. Upon the passing of Shah Walī Allāh in 1762, Shah ʿAbd al-ʿAzīz succeeded him as head of Madrasah Raḥīmiyyah, soon becoming the foremost Muslim scholar of his era. His students ultimately spread across every region of India, carrying his influence far and wide.</p>', 950, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (134, 'easy-good-deeds', 'easy-good-deeds', 661, 'Easy Good Deeds', NULL, '<p>A common misconception that discourages people from practicing Islam is the belief that its teachings are hard to follow. In reality, countless opportunities for earning immense reward appear in a person’s daily life and these are opportunities that often pass unnoticed simply because one is unaware of them.</p>', 450, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (135, 'munajat-maqbul-accepted-whispers', 'munajat-maqbul-accepted-whispers', 658, 'Munajat Maqbul – Accepted Whispers', NULL, '<p>There is no shortage of books on supplications, and scholars as well as the righteous friends of Allah ﷻ have compiled such works in every generation. However, this particular collection, prepared by Hakim al Ummah Hadrat Mawlana Ashraf Ali Thanawi Sahib, stands out for its careful attention to the authenticity of its sources. To enrich it further, we have also included the renowned <em>Hizb al-Baḥr</em> of Shaykh Abū’l-Ḥasan al-Shādhilī, along with <em>Zād al-Saʿīd (</em>the forty invocations of blessings upon the Prophet ﷺ) likewise compiled by Hakim al Ummah Hadrat Mawlana Ashraf Ali Thanawi Sahib.</p>', 450, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (136, 'a-sufi-study-of-hadith', 'a-sufi-study-of-hadith', 649, 'A Sufi Study of Hadith', NULL, '<p><strong>A Sufi Study of Hadith</strong><br><em>(Originally titled Haqiqa al-Tariqa min as-Sunna al-Aniqa)</em></p> <p><em>A Sufi Study of Hadith</em> is a unique commentary on a selection of over three hundred authentic hadith. Mawlānā Ashraf Ali Thanwī, one of the subcontinent’s greatest spiritual leaders and an exceptionally prolific author, translates, interprets, and provides commentary on each hadith from the perspective of <em>tasawwuf</em>. His explanations illuminate fine points of theology, moral conduct, etiquette, behaviour, and the customary practices of Sufis. Within the pages of this volume, readers encounter a dimension of Islam that is often little known and even less understood. For all seekers of truth, particularly those keen to deepen their understanding of the Prophet ﷺ’s teachings on <em>tasawwuf</em>, Mawlānā Thanwī’s work is invaluable. — Yusuf Talal DeLorenzo</p> <p>Mawlānā Ashraf Ali Thanwī (rahmatullāhi alayh) excelled in every branch of Islamic learning and was one of the most outstanding religious figures of the Islamic world in recent times. Perhaps his most enduring legacy is the widespread awareness, understanding, and acceptance of authentic <em>tasawwuf</em> among the masses. He is remembered as <strong>Hakīm al-Ummah</strong> (Physician of the Ummah) for his unmatched expertise in diagnosing spiritual ailments and providing effective remedies.</p> <p>In this book, Mawlānā Thanwī explores numerous subtle and complex themes of <em>tasawwuf</em> derived from the ahadith of our beloved Messenger ﷺ. His erudite commentary demonstrates repeatedly how the principles of <em>tasawwuf</em> are rooted in the primary sources of Islam. Following the methodology of his illustrious <em>mashā’ikh</em>, he emphasises the complete harmony between <em>Shariah</em> and <em>Tariqah</em>, and their interrelatedness.</p> <p>Thanks to Mawlānā Yusuf DeLorenzo’s translation, English-speaking Muslims can now access this valuable work. Studying it under the guidance of a qualified Shaykh will enhance the reader’s understanding and appreciation of the treasury of hadith, as well as the science of <em>tasawwuf</em>, proving beneficial for anyone traversing the spiritual path leading to Allah. — Shaykh Muhammad Saleem Dhorat (hafizahullāh)</p> <p>This volume revives the tradition of the earliest Sufis, who related hadiths of the Prophet ﷺ in seminal works such as Qushayrī’s <em>Risālah</em>, Makki’s <em>Qut al-Qulūb</em>, and Abū Nu‘aym’s <em>Ḥilyat al-Awliyā</em>. Imam Junayd stated:</p> <p><em>&#8220;The spiritual path is blocked shut, except to those who seek out the traces of the Chosen Prophet ﷺ; Say, ‘This is my path: I summon to Allah with full insight, I and whoever wholeheartedly follows me’&#8221;</em> [Qur’an 12:108].</p>', 900, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (137, 'living-as-a-muslim', 'living-as-a-muslim', 646, 'Living as a Muslim', NULL, '<p>This treatise by Hakīm al-Ummah Mawlānā Ashraf Ali al-Thanwī compiles approximately 90 Qur’anic verses and 340 Hadith under 25 thematic principles. It focuses on the essentials of Islam, encompassing both spiritual and legal dimensions. The spiritual exhortations include reliance upon the Divine, remembrance of Allah, love for Allah and His Messenger ﷺ, abstention from sin, gratitude, and patience. The legal commandments cover acts of worship and daily practice, such as prayer, Qur’anic recitation, fasting, Hajj, zakat, marriage, child-rearing, and proper social conduct.</p>', 600, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (138, 'imam-tahawis-sharh-maani-al-athar-explanation-of-the-meanings-of-the-t', 'imam-tahawis-sharh-maani-al-athar-explanation-of-the-meanings-of-the-traditions', 642, 'Imam Tahawi’s Sharh Maani Al-Athar – Explanation of the Meanings of the Traditions', NULL, '<p>Imām Ṭaḥāwī’s Sharḥ Maʿānī al-Āthār is a timeless and universal masterpiece from amongst the greatest compilations of Islamic literature. Consisting of a wide array of vast and unique Prophetic traditions, it is a detailed and indispensable resource in jurisprudential matters. As a key text within the Ḥanafī School of Law, it dispels the oft-assumed notion of the School being solely one of reason by substantiating many legal verdicts of the great luminary Imām Abū Ḥanīfah (Rh.) with not only the proposition of rationale but also with highly authentic supporting evidences. The key distinguishing factor of this work from others is its unmatchable style of composition and argumentation in deducing legal rulings and deeply analysing therein; all the while assisting its readers by explaining in a coherent, cogent, and comprehensive manner. As an outstanding treatise of Imām Ṭaḥāwi (Rh.) it embodies a lifetime of discerning sacred knowledge and formulating independent decisions based on such; pro- viding a glimpse into the depths and magnitudes of his knowledge. This book has been translated into English in the hope of making the text more accessible and enabling an appreciation for it amongst the masses.</p>', 2500, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (139, 'qawaid-fi-ulum-al-hadith-principles-of-hadith', 'qawaid-fi-ulum-al-hadith-principles-of-hadith', 639, 'Qawaid Fi Ulum al-Hadith (Principles of Hadith)', NULL, '<p><strong>Qawa’id Fi Ulum al-Hadith (Underlying Principles of the Sciences of Hadith)</strong><br><em>Also known as Muqaddima I‘la as-Sunan</em><br><em>By the critical Hadith scholar Mawlānā Zafar Ahmad al-Uthmānī</em></p> <p>The importance of Hadith as a foundation for Islamic law, theology, and ethics cannot be overstated. Alongside the Qur’an, it constitutes the second primary source for Shariah and the practice of Islam. While no Muslim questions the authority of the Prophet ﷺ, there are differing views regarding the precise determination of what the Prophet ﷺ said and did. These differences arise from the diverse methodologies employed in establishing the normative practices of the Prophet ﷺ. Across the spectrum of thought, opinions range from outright rejection of Hadith to a highly literalist reading of it.</p> <p>This translation offers another perspective on understanding Hadith. It presents the introduction to the extensive multi-volume work <em>I‘la as-Sunan</em>, which was originally written in response to the claim by the Ahl-e-Hadith that the school of Imam Abu Hanifah was deficient in Hadith.</p> <p>In this introduction, the author outlines his methodology for composing <em>I‘la as-Sunan</em>. He seeks to dismantle the misconception that the science of Hadith is absolute and fixed. He argues that, since Hadith science is not prescriptive in Shariah, no single group can claim exclusive authority or a universal understanding of it. This work will particularly appeal to students with an interest in abstract theory and methodology, as well as advanced students of Hadith and Islamic thought.</p> <p><strong>About the Author</strong></p> <p>Mawlānā Zafar Ahmad al-Uthmānī, the distinguished nephew of Hakīm al-Ummah Mawlānā Ashraf Ali Thanawi, was born on 13 Rabi al-Awwal 1310 AH / 1892 CE. Blessed with an exceptional memory, he memorised the Qur’an at a young age and, from the age of seven, studied mathematics, Persian, and Urdu under Mawlānā Yāsīn, the father of Mufti Shafi.</p> <p>He pursued Islamic sciences under various scholars, including his maternal uncle Hakīm al-Ummah, in Thana Bhawan and Kanpur. After obtaining licences (<em>ijazah</em>) in both sacred and rational sciences, he joined the Islamic seminary Mazahir Uloom and studied Hadith under the master and Gnostic Mawlānā Khalil Ahmad Saharanpuri. He received his licence to teach Hadith at the young age of 18.</p> <p>Mawlānā Zafar Ahmad al-Uthmānī subsequently became a professor of Islamic sciences at several institutions, including his alma mater Mazahir Uloom and Imdād al-Ulum in Thana Bhawan. He authored numerous works on the sacred sciences, with <em>I‘la as-Sunan</em> regarded as his magnum opus.</p>', 900, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (140, 'the-great-scholars-of-the-deoband-islamic-seminary', 'the-great-scholars-of-the-deoband-islamic-seminary', 634, 'The Great Scholars of The Deoband Islamic Seminary', NULL, '<p><strong>The Great Scholars of the Deobandi Seminary</strong></p> <p><em>The Great Scholars of the Deobandi Seminary</em> offers an inspiring glimpse into the lives and works of some of the luminaries affiliated with Dar al-Ulum Deoband, often described as the Azhar of the East. This book is a translation of two Urdu articles authored by Mufti Taqi Usmani, later published together under the title <em>Akabir-i Deoband Kya Thay</em>.</p> <p>The first article recounts a series of profound stories, teachings, and personal interactions that Mufti Taqi Usmani’s distinguished father, Mufti Muhammad Shafi Usmani, often shared with fondness, reflecting on his teachers and elders from whom he benefited. The second article, likewise a collection of stories and sayings, highlights the defining characteristics of those who emerged from the rich tradition of the Deoband seminary.</p> <p>In essence, this book captures the spirit and ethos of the Deoband seminary, offering invaluable insights into the character, legacy, and methodology of its great masters.</p> <p>The author, Mufti Taqi Usmani, is one of today’s leading contemporary scholars. After studying at Dar al-Ulum Karachi, Pakistan—a renowned institute established by his late father, Mufti Shafi Usmani—he has taught at the same institution for over four decades and currently instructs in <em>Sahih al-Bukhari</em>. In addition to his expertise in Islamic Law, Economics, and Hadith, he has authored more than forty books in Arabic, Urdu, and English on a wide range of topics.</p>', 500, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (141, 'the-book-of-remembrances-kitab-al-adhkar', 'the-book-of-remembrances-kitab-al-adhkar', 631, 'The Book Of Remembrances [Kitab al-Adhkar]', NULL, '<p><strong>The Book of Remembrances [Kitab al-Adhkar]</strong><br><em>By Imam Yahya ibn Sharaf an-Nawawi</em></p> <p><em>Kitab al-Adhkar</em> is the definitive compilation of remembrances (<em>dhikr</em>) and supplications (<em>du‘a</em>) as conveyed by the Prophet Muhammad ﷺ, the final Messenger of Allah. It provides a comprehensive guide to remembering and glorifying the Lord of the Universe, offering spiritual nourishment for every aspect of a believer’s daily life.</p> <p><em>Dhikr</em> and <em>du‘a</em> lie at the very heart of Islam, forming the essential connection between the Creator and His creation. As integral components of the Prophetic Sunna, they provide a divinely appointed means of approaching Allah for all needs, while reinforcing <em>tawḥīd</em>, the existential and cognitive unity that defines Muslim spirituality. The book also emphasises the importance of speaking only what is good and avoiding the sins of the tongue.</p> <p>The author, Muhy al-Din Yahya ibn Sharaf al-Nawawi (631–676 AH / 123–1277 CE), devoted his entire life to the pursuit of sacred knowledge and is revered throughout the Sunni world as one of its greatest authorities. Among his most famous works are <em>Al-Arba‘in</em> (a collection of forty hadiths), a commentary on Sahih Muslim, and <em>Kitab al-Adhkar</em>.</p> <p>This volume serves both as a reference guide and a source of inspiration. It provides a clear and elegant English translation of Imam al-Nawawi’s classic, including the full text of every prayer and invocation in both Arabic script and romanisation. It also incorporates all of the author’s statements about hadiths he narrated directly from his teachers, his guidance on the correct spelling and meanings of rare words and names, and scholarly notes supplementing his commentary on the sources of the hadiths.</p> <p><em>Revised and edited by Muhammad Isa Waley</em></p>', 2400, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (142, 'prophet-of-mercy', 'prophet-of-mercy', 628, 'Prophet Of Mercy', NULL, '<p><strong>Prophet of Mercy (Nabiyy-i-Rahmat) ﷺ</strong><br><em>By Shaykh Sayyid Abul-Hasan Ali Nadwi</em></p> <p>This book is the English translation of <em>as-Sirat an-Nabawiyyah</em>, a scholarly and thoroughly researched Arabic work by Shaykh Abul-Hasan Ali Nadwi. The title has been adopted from the Urdu translation of the same work. In this book, the author pays careful attention to the mindset, tastes, understanding, and sensibilities of the current generation. He also considers modern methods of research and discourse, ensuring that the content, evidence, and style are both accessible and impactful.</p> <p>In preparing this work, Shaykh Nadwi consulted a wide range of literature—both classical and contemporary, in Arabic and other languages—so that the book is not only comprehensive but also able to clarify misconceptions prevalent in modern thought. As a result, the work has received widespread acclaim and, within a short period, has been included in university syllabi. Now, the English version allows readers who are not proficient in Arabic or Urdu to benefit from this invaluable scholarship.</p> <p><strong>About the Author</strong></p> <p>Shaykh Abul-Hasan Ali Nadwi hailed from the Indian Hasani descendants of the Prophet ﷺ and belonged to a renowned scholarly family. Although originally from Rai Bareilly in Uttar Pradesh, he spent most of his life in Lucknow. He served as the Nazim (principal) and chair of the All-India Muslim Personal Law Board.</p> <p>A distinguished Islamic thinker, preacher, and guide, Shaykh Nadwi was also a prolific author with mastery of both oral and written Arabic and Urdu. Among his notable works is <em>What Has the World Lost Because of the Downfall of the Muslims?</em> His writings and speeches reflect deep empathy for humanity and present authentic Islamic thought and methodology.</p> <p>In addition to leading Nadwa and the Personal Law Board, he supported and guided numerous religious and social organizations. His religious and social activism spanned more than half a century, leaving a lasting impact on Islamic scholarship and public life.</p>', 1300, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (143, 'the-khulasa-a-summary-of-shamail-at-tirmidhi', 'the-khulasa-a-summary-of-shamail-at-tirmidhi', 625, 'The Khulasa – A Summary of Shamail at-Tirmidhi', NULL, '<p><strong>The Khulasa – A Summary of Abu Isa at-Tirmidhi’s <em>Ash-Shama’il al-Muhammadiyyah</em></strong></p> <p>This concise work presents a summary of Imam Abu Isa al-Tirmidhi’s <em>Ash-Shamail al-Muhammadiyya</em>, a celebrated text detailing the character, manners, and lifestyle of Allah’s Messenger ﷺ. Based primarily on the Moroccan scholar Sheikh Muhammad Abd Hayy al-Kattani’s summary, <em>Munyat al-Saa’il</em>, this book distills the essence of each chapter, allowing readers to draw closer to the Prophet ﷺ and study his distinguishing traits as if witnessing his blessed presence firsthand. In an age when many Muslims are becoming distant from the Messenger ﷺ (the lifeline of faith) this summary aims to rekindle love for him and inspire readers to emulate his noble example.</p> <p><strong>About Imam Abu Isa at-Tirmidhi</strong><br>Imam Abu Isa Muhammad ibn Isa ibn Sawra al-Tirmidhi was born in 210 AH in Termez, Uzbekistan. He travelled extensively in pursuit of prophetic hadiths, learning from luminaries such as Imams al-Bukhari, Muslim, Abu Dawud, Qutayba ibn Sa‘id, and Muhammad ibn Bashshar, among others. Renowned for his piety, asceticism, and remarkable memory, he authored several influential works, including <em>Ash-Shama’il al-Muhammadiyya</em> and <em>Al-Jami‘ al-Kabir</em> (commonly known as <em>Sunan al-Tirmidhi</em>). Imam al-Tirmidhi passed away in 297 AH.</p> <p><strong>About Sheikh Muhammad Abd al-Hayy al-Kattani</strong><br>Sheikh Muhammad Abd al-Hayy al-Kattani was born in 1302 AH in Fez, Morocco. He received his early education from his father, Sheikh Abd al-Kabir al-Kattani, and his brother, Sheikh Muhammad ibn Abd al-Kabir, before studying under prominent scholars at the renowned institute of Kairouan. He travelled widely across Morocco, Egypt, Syria, and the Holy Lands, benefitting from the knowledge of many scholars. Later in life, facing difficulties with the authorities in Morocco, he emigrated to Nice, France, where he passed away in 1382 AH.</p>', 400, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (144, 'lessons-in-islamic-history', 'lessons-in-islamic-history', 621, 'Lessons In Islamic History', NULL, '<p><em>Lessons in Islamic History</em> is a concise yet comprehensive summary of Shaykh Muhammad Khudari Bak’s groundbreaking works on Islamic history. In this series, the pioneering Egyptian historian and scholar of Shari‘ah and Arabic literature distills the essence of his three seminal studies on the Prophetic Biography, the Rightly-Guided Caliphs, and the Umayyad and ‘Abbasid Dynasties. In his distinctively eloquent yet accessible style, he traces the evolving political and social circumstances of the Muslim peoples, from their origins in the pre-Islamic Arabian Peninsula to his own era in the Ottoman Khedivate of Egypt.</p> <p>An instinctive educator, Shaykh Khudari Bak emphasized that he wrote not merely to record history, but so that history might serve as a source of guidance. With refreshing objectivity and restraint, he presents the vicissitudes of Islamic history, highlighting the lessons to be drawn from past events. In an age where competing historical narratives often clash, this text offers a clear and concise account of Muslim leadership and its consequences for the Ummah. It is, therefore, an indispensable read for both young and old alike.</p>', 1000, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (145, 'birr-al-walidayn-being-dutiful-to-parents', 'birr-al-walidayn-being-dutiful-to-parents', 616, 'Birr al Walidayn (Being Dutiful to Parents)', NULL, '<p><em>Birr al-Walidayn</em> is a concise treatise on the subject of dutifulness to parents, recently published for the first time. Its significance lies in the fact that Imam al-Bukhari appears to be the first Muhadith to compile a work dedicated specifically to this topic. The treatise contains 75 ḥadīths, organised under various chapter headings that revolve around two central themes: being dutiful to one’s parents and maintaining family ties. This English translation is accompanied by succinct and insightful commentary from , as well as appendices featuring the narrations transmitted by Imam al-Bukhari on the same subject in his <em>Ṣaḥīḥ</em> and <em>Al-Adab al-Mufrad</em>, along with chains of transmission and biographical notes on the narrators.</p>', 600, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (146, 'islam-politics', 'islam-politics', 598, 'Islam & Politics', NULL, '<p>What does an authentic Islamic government look like, and how is it meant to function? In this concise yet wide-ranging work, the esteemed scholar Muftī Muḥammad Taqī ʿUthmānī offers an authoritative overview of the guidance provided by the foundational Islamic sources on political life. Across six chapters, he examines the nature and purpose of politics in Islam through the lens of the Qurʾān and the Prophetic Sunnah; the principles governing the formation of a government; the rules and procedures for administering it; the Islamic directives regarding defence and foreign policy; and the conditions under which it may become permissible to remove a ruler or government from office.</p> <p>The book concludes with two additional essays by the author addressing political matters with particular reference to Pakistan. <em>Islam and Politics</em> is indispensable reading for anyone seeking a clear, accessible, and reliable exposition of Islam’s fundamental teachings on governance and political engagement.</p> <p>Muftī Muḥammad Taqī ʿUthmānī is among the world’s most distinguished scholars of the Islamic sciences and a former Justice of the High Court of Pakistan. Born in 1943 in Deoband, India, he pursued his studies with leading ʿulamāʾ in Karachi and beyond. His primary fields of expertise include ḥadīth, jurisprudence, Ṣūfism, and Islamic economics. He has authored numerous works— in Urdu, Arabic, and English—covering these and other areas of Islamic scholarship.</p>', 900, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (147, 'riyad-as-salihin-abridged-and-annotated', 'riyad-as-salihin-abridged-and-annotated', 590, 'Riyad as-Salihin – Abridged and Annotated', NULL, '<p>In 13th-century Damascus, the renowned ḥadīth scholar, jurist, academic luminary, and devoted ascetic Imām Muḥyī al-Dīn Abū Zakariyyā Yaḥyā ibn Sharaf al-Nawawī undertook the task of compiling a concise collection of rigorously authenticated ḥadīths that would serve as a path to the Hereafter for its reader. The result was <em>Riyāḍ al-Ṣāliḥīn</em>, a compilation of nearly two thousand ḥadīths covering a wide range of subjects, selected from the <em>Ṣaḥīḥayn</em> and other authoritative works of the Sunnah.</p> <p>This blessed work—brimming with the pearls of the noble Sunnah and Prophetic guidance—was met with immediate scholarly acclaim. Over the centuries, it has firmly established its value through the profound and enduring impact it has had on Muslim character, conduct, education, and spiritual reform throughout the Ummah.</p>', 1700, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (148, 'radiant-prayers', 'radiant-prayers', 584, 'Radiant Prayers', NULL, '<p>Calling upon Allāh is at the very heart of worship and an essential element of a believer’s daily life. It is among the most powerful means of nurturing a deep and intimate relationship with the Creator. Throughout the day, a believer should remain in a state of continually asking Allāh for every need—whether great or small.</p> <p>While a person may supplicate in any language and in their own words, the duʿās taught in the Qurʾān and Sunnah possess a distinct excellence and carry profound spiritual benefits. Each supplication contains layers of meaning and wisdom. For this reason, one should strive to memorise these duʿās along with their translations and make a habit of reciting them at meaningful moments throughout life.</p>', 400, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (149, 'usul-al-shashi-2', 'usul-al-shashi', 578, 'Usul al-Shashi', NULL, '<p>How does one navigate the seemingly vast and conflicting body of primary Islamic sources? What should a student do when encountering differing practices of the Prophet ﷺ on the very same matter? When is a particular action considered obligatory, recommended, or merely permissible? These are among the central questions addressed in uṣūl al-fiqh.</p> <p>Often translated—though somewhat inadequately—as “principles of Islamic jurisprudence,” uṣūl al-fiqh is the legal theory that forms the foundation of Islamic substantive law and practical ethics.</p> <p>Uṣūl al-Shāshī is a concise introductory treatise on legal theory according to the Ḥanafī school. It holds a place of prominence within the dars-i-niẓāmī curriculum taught in South Asian seminaries and in affiliated institutions across the globe, despite the relative obscurity surrounding its author.</p> <p>This translation is designed to be accessible to a broad readership, especially beginners in Islamic law and readers with a keen interest in legal theory.</p>', 1000, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (150, 'the-virtues-and-rulings-of-salat-at-tasbih', 'the-virtues-and-rulings-of-salat-at-tasbih', 573, 'The Virtues and Rulings of Salat at-Tasbih', NULL, '<p>The Virtues and Rulings of Ṣalāt at-Tasbīḥ (Ṣalāt at-Tasbīḥ ke Faḍāʾil aur Masāʾil) is a unique work detailing an optional prayer prescribed by the Prophet Sallahu Alahyi wa Sallam to his Companions. This short treatise includes hadiths related to the virtues of this prayer, along with the various methods and rulings regarding it. The author supplements the work with a section for advanced students, discussing the authenticity of the hadiths prescribing this prayer.</p> <p>About the author</p> <p>Shaykh Mufti ʿAbd al-Raʾūf Sakkharwī was born in 1951 in Sukkur, a city in the Sindh province of Pakistan. He received his early Islamic education in his hometown and then completed his final year of the ʿālimiyyah course, as well as his masterslevel studies, at Dār al-ʿUlūm Karachi under Shaykh Muftī Muḥammad Shafīʿ and others.</p> <p>Shaykh Mufti ʿAbd al-Raʾūf Sakkharwī is currently a senior Mufti at the Dār al-Iftāʾ in Dār al-ʿUlūm Karachi, where he has taught portions of Saḥīḥ Muslim for several years. He is also the author of many beneficial Urdu-language works, some of which have been translated into English, such as: Virtuous Deeds &amp; Consigning their Reward to Others, How Muslim Women Offer Prayers, and Customary Collective Recital of Qur’an from a Shari’ah Perspective.</p>', 200, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (151, 'the-path-to-paradise-principles-of-good-character-appreciation-of-the', 'the-path-to-paradise-principles-of-good-character-appreciation-of-the-hereafter', 569, 'The Path to Paradise – Principles of Good Character & Appreciation of the Hereafter', NULL, '<p><strong>Translation of <em>Allāh Taʿālā se Sharam Kījiye</em></strong><br><strong>By Mufti Muḥammad Salmān Manṣūrpūrī</strong></p> <p><em>The Path to Paradise</em> is an in-depth commentary on the ḥadīth “Be modest [istaḥyū] before Allah, as is His due”, narrated by Imam Tirmidhi. It expounds upon Divine and Prophetic teachings and presents scholarly discussions on a wide range of themes: cultivating sincere belief in Allāh; the various dimensions of spiritual purification; employing the limbs in a manner sanctioned by the Sharīʿah; maintaining integrity in financial dealings; observing proper etiquette in social conduct; and reflecting on death along with its related rulings.</p> <p>The work concludes with a comprehensive account of the major signs that will precede the End of Time, followed by a detailed description of the stages of life after death—within the grave, on the Day of Judgement, and ultimately, the final abodes of Paradise and Hell.</p>', 700, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (152, 'hijab-a-comprehensive-introduction', 'hijab-a-comprehensive-introduction', 559, 'Hijab: A Comprehensive Introduction', NULL, '<p><strong>Tafṣīl al-Khiṭāb fī Āyāt al-Ḥijāb</strong> (From <strong>Aḥkām al-Qurʾān</strong>)</p> <p>Supplemented By Three Appendices:</p> <ul> <li> <p>Women’s attendance at the masjid for prayer</p> </li> <li> <p>Travelling without a maḥram</p> </li> <li> <p>The intermingling of genders</p> </li> </ul> <p>It Includes an extensive Biography of Shaykh Muftī Muḥammad Shafīʿ<br>From Ḥayāt-i-Muftī-i-Aʿẓam by Muftī Muḥammad Rafīʿ ʿUthmānī &amp; Other Reputable Sources</p> <p>This Annotated Translation of Shaykh Muftī Muḥammad Shafīʿ’s Seminal Work</p> <p>Muftī Taqī ʿUthmānī writes:<br>“Books on the topic of women’s veiling and unveiling have proliferated in our time. The best I have seen on the subject is a monograph by my late father, Shaykh Muftī Muḥammad Shafīʿ (Allah have mercy on him), called Tafṣīl al-Khiṭāb fī Āyāt al-Ḥijāb, which forms part of his Aḥkām al-Qurʾān. In it, he conducted a thorough examination of the verses and ḥadīths on the subject and elaborated on the views of the jurists and the commentaries of the exegetes about the boundaries and method of ḥijāb. (Takmīlah Fatḥ al-Mulhim, 4:153)”</p>', 950, 3, 0, 'live');
INSERT INTO books (id, slug, legacy_slug, legacy_wc_id, title, title_ar, description_html, price_pence, stock, reserved, status) VALUES (153, 'an-essential-guide-to-islam-evolution', 'islam-and-evolution', 536, 'An Essential Guide to Islam & Evolution', NULL, '<p><strong>An Essential Guide to Islam and Evolution</strong> <p>The Design Argument in Classical Islamic Thought • Islamic Scripture on Biological Origins • A Scientific and Philosophical Appraisal of Modern Evolutionary Theory</p> <p><strong>By Muftī Zameelur Raḥmān</strong></p> <p>Featuring Translations of:</p> <ul> <li> <p><strong>Shaykh Muṣṭafā Ṣabrī’s</strong> theological and rational critiques of human evolution</p> </li> <li> <p><strong>Shaykh Ashraf ʿAlī Thānawī’s</strong> critique of Darwinian evolution</p> </li> </ul> <p><strong>Paperback • 381 pages</strong><br><strong>ISBN:</strong> 978739753023<br><strong>As-Subah Publications</strong></p> <p>A vital resource for readers seeking a comprehensive, lucid, and orthodox Islamic perspective on evolution.</p> <p>This work explores a wide range of topics, including:</p> <p><strong>(a)</strong> The design argument in both classical Islamic scholarship and modern scientific and philosophical discussions<br><strong>(b)</strong> A critique of <em>methodological naturalism</em> as a foundational principle in contemporary science<br><strong>(c)</strong> An Islamic framework for understanding the nature and possibility of miracles<br><strong>(d)</strong> A critical assessment of current scientific positions on naturalistic evolution<br><strong>(e)</strong> Scriptural evidence from the Islamic tradition concerning biological origins<br><strong>(f)</strong> A critique of attempts to harmonise Islamic scripture with naturalistic evolutionary models</p> <p>The concluding appendices present writings from leading scholars of the past century — <strong>Shaykh Muṣṭafā Ṣabrī</strong>, <strong>Shaykh Ashraf ʿAlī Thānawī</strong>, and <strong>Shaykh Anwar Shāh Kāshmīrī</strong> — illustrating how deeply rooted traditional scholars engaged with these debates long before they re-emerged in modern discourse.</p></p>', 1400, 3, 0, 'live');
